def _hash_pwd(uid: int, password: str) -> str:
    """SHA-256 с солью uid."""
    return hashlib.sha256(f"{uid}:{password}".encode()).hexdigest()

def _auth_sheet():
    """Лист auth для хэшей паролей. Создаёт если нет."""
    try:
        sp = gc.open_by_key(PASSWORDS_SHEET_ID)
        try:
            return sp.worksheet(PASSWORDS_AUTH_SHEET)
        except Exception:
            sh = sp.add_worksheet(title=PASSWORDS_AUTH_SHEET, rows=100, cols=3)
            sh.update("A1:C1", [["uid", "password_hash", "created_at"]])
            return sh
    except Exception as e:
        logger.error(f"Auth sheet: {e}"); return None

def _get_user_hash(uid: int) -> str | None:
    sh = _auth_sheet()
    if not sh: return None
    rows = sh.get_all_values()
    for i, r in enumerate(rows):
        if i == 0: continue
        if len(r) >= 2 and r[0].strip() == str(uid):
            return r[1].strip()
    return None

def _set_user_hash(uid: int, pwd_hash: str):
    sh = _auth_sheet()
    if not sh: return
    rows = sh.get_all_values()
    for i, r in enumerate(rows):
        if i == 0: continue
        if len(r) >= 1 and r[0].strip() == str(uid):
            sh.update_cell(i + 1, 2, pwd_hash)
            return
    sh.append_row([str(uid), pwd_hash, datetime.datetime.now().strftime("%d.%m.%Y %H:%M")])

def _is_authed(uid: int) -> bool:
    ts = auth_sessions.get(uid, 0)
    return (time.time() - ts) < AUTH_TTL_SEC

