def allowed(uid): return uid in ALLOWED_USERS

def detect_operator(raw):
    if not raw: return ""
    low = raw.lower().strip()
    for k, v in COMPANY_TO_OPERATOR.items():
        if k in low: return v
    for op in OPERATORS:
        if op.lower() in low: return op
    return ""

def auto_article(doc_type, operator, is_incoming=False):
    dt = (doc_type or "").lower()
    if "возврат" in dt: return "04. Прочие расходы. Возврат"
    if is_incoming: return "01. Доходы. Анастасия"
    if "чек" in dt or "доход" in dt or "поступлен" in dt: return "01. Доходы. Анастасия"
    if "комисси" in dt: return "03. Переменные расходы. Комиссия банка"
    # «02. Оплата туроператору» — ТОЛЬКО если doc_type явно говорит про исходящий платёж.
    # Иначе (выписка / crm / другое / пусто) оставляем пусто — пользователь выберет сам.
    is_outgoing_payment = any(s in dt for s in ("платеж", "платёж", "оплата", "сбп", "перевод", "отправлен"))
    if is_outgoing_payment and operator:
        for a in ARTICLES:
            if a.startswith("02.") and operator in a and "Сборный" not in a: return a
    return ""

def apply_sign(amount, article):
    try: val = abs(float(str(amount).replace(",",".").replace(" ","")))
    except Exception: return amount
    return val if article.startswith("01.") else -val


def format_note(note_num, note_type):
    if not note_num: return ""
    n = str(note_num).strip()
    t = (note_type or "").strip().lower()
    if t == "фд" and not n.lower().startswith("фд"): return f"ФД {n}"
    if t == "пп" and not n.lower().startswith("пп"): return f"пп {n}"
    return n

def clear_all_states(uid):
    user_states.pop(uid, None); batch_docs.pop(uid, None); guide_docs.pop(uid, None); pending_delete.pop(uid, None)
    reflection_states.pop(uid, None)
    try: cal_states.pop(uid, None)
    except Exception: pass
    try:
        from uon_module import uon_states as _uon_states
        _uon_states.pop(uid, None)
    except Exception: pass
    try:
        if nutrition_module:
            nutrition_module.nutr_states.pop(uid, None)
    except Exception: pass
    try:
        if warmup_module:
            warmup_module.warmup_states.pop(uid, None)
    except Exception: pass

@router.message_callback(F.callback.payload == "reset")
async def cb_reset(event: MessageCallback):
    cb = event.callback
    msg = event.message
    clear_all_states(cb.user.user_id)
    await msg.answer(text="🏠 Главное меню:", attachments=[KB_MAIN]); await event.bot.send_callback(cb.callback_id, notification=" ")

@router.message_created(F.message.body.text == "/start")
async def cmd_start(event: MessageCreated):
    msg = event.message
    logger.info(f"START from uid={msg.sender.user_id}, allowed={ALLOWED_USERS}")
    if not allowed(msg.sender.user_id): return await msg.answer(text="Нет доступа.")
    clear_all_states(msg.sender.user_id)
    await msg.answer(text="👋 Привет! Выбери раздел:", attachments=[KB_MAIN])

