# -- Калькулятор валют --
# CALC_OPERATORS определён ниже, после объявления функций fetch_*

def _parse_rates_from_text(text: str) -> tuple[float, float]:
    """Извлекает USD и EUR курсы из строки вида '1 USD = 74.57 ₽ \n 1 EUR = 86.77 ₽'."""
    m_usd = re.search(r'USD\s*=\s*([\d.,]+)', text)
    m_eur = re.search(r'EUR\s*=\s*([\d.,]+)', text)
    usd = float(m_usd.group(1).replace(",", ".")) if m_usd else 0.0
    eur = float(m_eur.group(1).replace(",", ".")) if m_eur else 0.0
    return usd, eur

