def extract_guide_from_row(row, gs):
    """Извлекает данные гида из строки с учётом маппинга столбцов."""
    cols = gs["cols"]
    
    def get(idx):
        return row[idx].strip() if idx is not None and idx < len(row) else ""
    
    # Обработка разных структур
    if "city_country" in cols:
        # Формат: "Город, Страна" или "Город" в одном столбце
        city_country = get(cols["city_country"])
        parts = [p.strip() for p in city_country.split(",")]
        if len(parts) >= 2:
            city = parts[0]
            country = parts[-1]
        else:
            city = city_country
            country = ""
    else:
        country = get(cols.get("country"))
        city = get(cols.get("city"))
    
    name = get(cols.get("name"))
    contacts = get(cols.get("contacts"))
    desc = get(cols.get("desc"))
    link = get(cols.get("link")) if "link" in cols else ""
    
    # Если есть ссылка — добавляем к контактам
    if link and link not in contacts:
        contacts = f"{contacts}, {link}" if contacts else link
    
    return {
        "country": country.upper() if country else "",
        "city": city,
        "name": name,
        "contacts": contacts,
        "desc": desc,
        "source": gs["name"],
    }

def fill_grouped_countries(all_rows, country_col, header_row):
    """В таблицах где страна указана один раз для группы строк,
    заполняет пустые ячейки страны значением сверху."""
    result = []
    last_country = ""
    for i, row in enumerate(all_rows):
        if i < header_row: continue
        if not any((c or "").strip() for c in row): continue  # пустая строка
        row_copy = list(row)
        cell = (row_copy[country_col] if country_col < len(row_copy) else "").strip()
        if cell:
            last_country = cell
        elif last_country:
            # Дополняем пустую ячейку страны
            while len(row_copy) <= country_col:
                row_copy.append("")
            row_copy[country_col] = last_country
        result.append(row_copy)
    return result

def auto_detect_columns(all_rows, header_row, default_cols):
    """Автоопределение столбцов по заголовку листа."""
    if header_row - 1 >= len(all_rows):
        return default_cols
    header = [c.lower().strip() for c in all_rows[header_row - 1]]
    detected = {}
    mappings = {
        "country": ["страна", "регион", "region", "country"],
        "city": ["город", "city"],
        "name": ["гид", "фио", "имя", "представитель", "наименование", "name", "guide"],
        "contacts": ["контакты", "телефон", "contact", "ссылка на профиль"],
        "desc": ["описание", "description", "комментарий"],
        "link": ["ссылка", "link", "url", "ссылка на сайт"],
    }
    for key, keywords in mappings.items():
        for i, h in enumerate(header):
            if any(kw in h for kw in keywords):
                detected[key] = i
                break
    # "Город/Страна" в одном столбце
    for i, h in enumerate(header):
        if "город" in h and "страна" in h:
            detected["city_country"] = i
            detected.pop("city", None)
            detected.pop("country", None)
    # 3-колоночные листы (Наименование | Сайт | Описание)
    if not detected:
        return default_cols
    if "name" not in detected:
        for i, h in enumerate(header):
            if "наименование" in h or "название" in h or "за чем обращаются" in h:
                detected["name"] = i; break
    if "contacts" not in detected:
        for i, h in enumerate(header):
            if "сайт" in h or "site" in h:
                detected["contacts"] = i; break
    return detected if detected else default_cols



def search_guides_data(query):
    """Чистая функция поиска гидов. Возвращает (found_list, errors_list)."""
    q = query.lower().strip()
    found = []
    errors = []

    for src in GUIDE_SOURCES:
        try:
            spreadsheet = gc.open_by_key(src["id"])
            worksheets = spreadsheet.worksheets()
            for ws in worksheets:
                try:
                    all_rows = ws.get_all_values()
                    if len(all_rows) <= 1: continue
                    header_row = src.get("header_row", 1)
                    default_cols = src["cols"]
                    actual_cols = auto_detect_columns(all_rows, header_row, default_cols)
                    if "country" in actual_cols:
                        rows = fill_grouped_countries(all_rows, actual_cols["country"], header_row)
                    else:
                        rows = [list(r) for i, r in enumerate(all_rows) if i >= header_row and any((c or "").strip() for c in r)]
                    sheet_label = ws.title
                    for row in rows:
                        row_text = " ".join([(c or "") for c in row]).lower()
                        if fuzzy_match(q, row_text):
                            guide = extract_guide_from_row(row, {"cols": actual_cols, "name": sheet_label})
                            if guide["name"] or guide["contacts"]:
                                found.append(guide)
                except Exception as e:
                    logger.warning(f"Sheet '{ws.title}': {e}")
        except Exception as e:
            logger.error(f"Spreadsheet {src['name']}: {e}")
            errors.append(src["name"])
    return found, errors

async def search_guides(msg, query):
    """Ищет гидов по стране, городу или имени — по ВСЕМ таблицам и ВСЕМ листам."""
    try:
        found, errors = search_guides_data(query)

        if not found:
            err_note = ""
            if errors:
                err_note = f"\n\n⚠️ Не удалось прочитать: {', '.join(errors)}.\nДай доступ сервисному аккаунту."
            await msg.answer(text=f"🔍 По запросу «{query}» ничего не найдено.{err_note}\n\nПопробуй другой запрос или /find")
            return

        # Формируем карточки
        cards = []
        for g in found:
            card = ""
            card += f"● <b>{g['country']}</b>"
            if g["city"]: card += f", {g['city']}"
            card += "\n"
            if g["name"]: card += f"  {g['name']}\n"
            if g["contacts"]: card += f"  тел: {g['contacts']}\n"
            if g["desc"]:
                short_desc = g["desc"][:200] + ("..." if len(g["desc"]) > 200 else "")
                card += f"  {short_desc}\n"
            cards.append(card)

        header = f"• <b>Найдено: {len(found)}</b> (запрос: «{query}»)\n\n"
        batch_size = 10
        for batch_idx in range(0, len(cards), batch_size):
            batch = cards[batch_idx:batch_idx + batch_size]
            if batch_idx == 0:
                text = header + "\n".join(batch)
            else:
                text = f"<i>({batch_idx+1}-{min(batch_idx+batch_size, len(cards))} из {len(found)}):</i>\n\n" + "\n".join(batch)

            if batch_idx + batch_size >= len(cards):
                kb = _make_kb([
                    [CallbackButton(text="Новый поиск", payload="guide_search_start")],
                    [CallbackButton(text="В начало", payload="reset")],
                ])
                await msg.answer(text=text, attachments=[kb])
            else:
                await msg.answer(text=text)

    except Exception as e:
        logger.error(f"Search global: {e}")
        err_str = str(e)
        if "SSL" in err_str or "ClientOS" in err_str or "ConnectionReset" in err_str:
            await msg.answer(text="⚠️ Сетевая ошибка, попробуй ещё раз через несколько секунд.")
        else:
            await msg.answer(text=f"Ошибка поиска: {err_str[:100]}")

