# ==================== ГОЛОСОВЫЕ СООБЩЕНИЯ ====================
# Распознавание через Сбер SaluteSpeech: бесплатный лимит 60 мин/мес для PERS-тарифа.
# Авторизация — Authorization Key (base64 Client_ID:Client_Secret) в env SBER_AUTH_KEY.

# Возможные имена переменной — проверяем подряд, чтобы переживать опечатки/варианты
_SBER_ENV_NAMES = ("SBER_AUTH_KEY", "SBER_API_KEY", "SBER_KEY",
                   "SALUTE_AUTH_KEY", "SBERAUTHKEY")


_sber_key_sheet_cache: tuple[str, float] | None = None  # (key, fetched_at)


def _read_sber_key_from_sheet() -> str:
    """Fallback: читает SBER ключ из листа 'config' таблицы КУДиР (cell B1).
    Используется когда Railway не инжектит env-переменную в контейнер.
    Кэшируем на 5 минут, чтобы не дёргать Sheets на каждое голосовое."""
    global _sber_key_sheet_cache
    if _sber_key_sheet_cache and (time.time() - _sber_key_sheet_cache[1]) < 300:
        return _sber_key_sheet_cache[0]
    try:
        sp = gc.open_by_key(SPREADSHEET_ID_2)
        try:
            ws = sp.worksheet("config")
        except Exception:
            return ""
        rows = ws.get_all_values()
        for r in rows:
            if len(r) >= 2 and r[0].strip().upper() == "SBER_AUTH_KEY":
                key = r[1].strip()
                if key:
                    _sber_key_sheet_cache = (key, time.time())
                    return key
        return ""
    except Exception as e:
        logger.warning(f"Sber key from sheet failed: {e}")
        return ""


def _read_sber_key() -> str:
    """Читает SBER ключ: сначала env, потом fallback в Google Sheets (config-лист
    в КУДиР-таблице). Не кэширует env, чтобы переживать поздно-добавленные переменные."""
    for name in _SBER_ENV_NAMES:
        v = (os.environ.get(name) or "").strip()
        if v:
            return v
    return _read_sber_key_from_sheet()


# Диагностика при старте: выводим какие env-переменные с похожими именами видит процесс.
# Если в Railway переменная установлена, но не инжектится в контейнер — это будет видно тут.
_relevant_env = {k: len(v or "") for k, v in os.environ.items()
                 if any(s in k.upper() for s in ("SBER", "SALUTE", "GROQ", "WHISPER", "SPEECH"))}
if _relevant_env:
    logger.info(f"Voice-related env keys seen by process: {_relevant_env}")
else:
    logger.info("Voice-related env keys: НИ ОДНОЙ не видно в os.environ (Sber/Salute/Groq/Whisper/Speech)")
_initial_key = _read_sber_key()
if _initial_key:
    logger.info(f"SBER key OK at start: prefix={_initial_key[:6]}…, length={len(_initial_key)}")
else:
    logger.warning(
        "SBER key NOT FOUND at start. Проверь в Railway → Variables: "
        f"переменная должна называться одним из: {_SBER_ENV_NAMES}. "
        "Бот будет re-читать env при каждом голосовом — если ты добавишь позже, перезапуск не нужен."
    )

_sber_token: tuple[str, int] | None = None  # (access_token, expires_at_ms)
_sber_token_lock = asyncio.Lock()


async def _sber_get_access_token() -> str:
    """Получает access_token у Sber NGW. Кэширует в памяти 30 мин.
    Re-читает env-переменную при каждом вызове, чтобы выживать кейс «переменная
    добавлена в Railway после старта процесса»."""
    global _sber_token
    now_ms = int(time.time() * 1000)
    if _sber_token and (_sber_token[1] - now_ms) > 60_000:
        return _sber_token[0]
    async with _sber_token_lock:
        now_ms = int(time.time() * 1000)
        if _sber_token and (_sber_token[1] - now_ms) > 60_000:
            return _sber_token[0]
        sber_key = _read_sber_key()
        if not sber_key:
            seen = [k for k in os.environ if any(s in k.upper() for s in ("SBER","SALUTE","SPEECH"))]
            raise Exception(
                f"SBER ключ не найден в env. Проверял имена: {_SBER_ENV_NAMES}. "
                f"В env вижу похожие ключи: {seen or 'НИ ОДНОГО'}. "
                "В Railway → Variables проверь: 1) точное имя SBER_AUTH_KEY, "
                "2) что значение не пустое, 3) что переменная в нужном environment."
            )
        import urllib.request, urllib.error, ssl, uuid as _uuid
        rquid = str(_uuid.uuid4())
        req = urllib.request.Request(
            "https://ngw.devices.sberbank.ru:9443/api/v2/oauth",
            data="scope=SALUTE_SPEECH_PERS".encode(),
            headers={
                "Authorization": f"Basic {sber_key}",
                "RqUID": rquid,
                "Content-Type": "application/x-www-form-urlencoded",
                "Accept": "application/json",
            },
            method="POST",
        )
        # Sber endpoints используют сертификаты Минцифры РФ, которых нет в стандартных
        # CA-бандлах. Чтобы не тащить cert-файл — отключаем проверку (риск MITM минимален:
        # запрос идёт по HTTPS на известный домен, в теле — короткоживущий токен).
        ctx = ssl._create_unverified_context()
        def _do():
            try:
                with urllib.request.urlopen(req, timeout=30, context=ctx) as r:
                    return json.loads(r.read())
            except urllib.error.HTTPError as e:
                body = e.read().decode("utf-8", errors="ignore")[:300]
                raise Exception(f"Sber OAuth {e.code}: {body}")
        result = await asyncio.to_thread(_do)
        token = result.get("access_token")
        expires_at = int(result.get("expires_at") or 0)
        if not token:
            raise Exception(f"Sber OAuth: нет access_token в ответе ({result})")
        _sber_token = (token, expires_at)
        return token


def _sber_sync_recognize_sync(voice_data: bytes, token: str) -> str:
    """Синхронное распознавание Сбер (до ~1 мин аудио)."""
    import urllib.request, urllib.error, ssl
    ctx = ssl._create_unverified_context()
    url = "https://smartspeech.sber.ru/rest/v1/speech:recognize?model=general&language=ru-RU"
    req = urllib.request.Request(
        url, data=voice_data,
        headers={"Authorization": f"Bearer {token}", "Content-Type": "audio/ogg;codecs=opus"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=90, context=ctx) as r:
            result = json.loads(r.read())
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", errors="ignore")[:400]
        logger.error(f"Sber STT {e.code}: {body}")
        raise Exception(f"Sber STT {e.code}: {body}")
    pieces = result.get("result") or []
    if isinstance(pieces, list) and pieces:
        text = " ".join(p.strip() for p in pieces if isinstance(p, str)).strip()
    else:
        text = str(pieces).strip() if pieces else ""
    if not text:
        raise Exception(f"Sber вернул пустой результат: {str(result)[:200]}")
    return text


def _collect_sber_text(obj) -> list:
    """Рекурсивно собирает распознанный текст из ответа async-распознавания."""
    out = []
    if isinstance(obj, dict):
        if isinstance(obj.get("normalized_text"), str):
            out.append(obj["normalized_text"])
        elif isinstance(obj.get("text"), str):
            out.append(obj["text"])
        else:
            for v in obj.values():
                out += _collect_sber_text(v)
    elif isinstance(obj, list):
        for v in obj:
            out += _collect_sber_text(v)
    return out


def _sber_async_recognize_sync(voice_data: bytes, token: str) -> str:
    """Асинхронное распознавание Сбер (для аудио длиннее ~1 мин):
    upload → speech:async_recognize → опрос task:get → data:download."""
    import urllib.request, urllib.error, ssl, time
    ctx = ssl._create_unverified_context()
    base = "https://smartspeech.sber.ru/rest/v1"

    def call(path, data=None, method="GET", ctype=None):
        headers = {"Authorization": f"Bearer {token}"}
        if ctype: headers["Content-Type"] = ctype
        req = urllib.request.Request(base + path, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=120, context=ctx) as r:
                return json.loads(r.read())
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", errors="ignore")[:300]
            logger.error(f"Sber async {path} {e.code}: {body}")
            raise Exception(f"Sber async {path} {e.code}: {body}")

    up = call("/data:upload", data=voice_data, method="POST", ctype="audio/ogg;codecs=opus")
    file_id = (up.get("result") or {}).get("request_file_id")
    if not file_id:
        raise Exception(f"Sber upload без request_file_id: {str(up)[:200]}")
    body = json.dumps({
        "options": {"model": "general", "audio_encoding": "OPUS", "language": "ru-RU"},
        "request_file_id": file_id,
    }).encode()
    tk = call("/speech:async_recognize", data=body, method="POST", ctype="application/json")
    task_id = (tk.get("result") or {}).get("id")
    if not task_id:
        raise Exception(f"Sber async без task id: {str(tk)[:200]}")
    response_file_id = None
    for _ in range(80):  # ~4 минуты опроса
        st = call(f"/task:get?id={task_id}")
        res = st.get("result") or {}
        status = res.get("status")
        if status == "DONE":
            response_file_id = res.get("response_file_id"); break
        if status in ("ERROR", "CANCELED"):
            raise Exception(f"Sber async статус {status}: {str(st)[:200]}")
        time.sleep(3)
    if not response_file_id:
        raise Exception("Sber async: задача не завершилась за отведённое время")
    dl = call(f"/data:download?response_file_id={response_file_id}")
    parts = _collect_sber_text(dl)
    text = " ".join(p.strip() for p in parts if p and p.strip()).strip()
    if not text:
        raise Exception(f"Sber async пустой результат: {str(dl)[:200]}")
    return text


async def _transcribe_voice(msg) -> str:
    """Распознаёт голосовое через Сбер SaluteSpeech.
    Короткое (≤~1 мин) — sync; длинное — async-пайплайн."""
    voice_data = await _download_attachment_bytes(msg)
    if d is None: await msg.answer(text="⚠️ Не удалось получить вложение."); return
    token = await _sber_get_access_token()
    duration = 0
    if duration > 55:
        return await asyncio.to_thread(_sber_async_recognize_sync, voice_data, token)
    try:
        return await asyncio.to_thread(_sber_sync_recognize_sync, voice_data, token)
    except Exception as e:
        low = str(e).lower()
        # Длинное аудио, отклонённое sync-эндпоинтом → пробуем async
        if any(s in low for s in ("too long", "longer", "duration", "exceed", "large", " 413", "413:")):
            logger.info("Sber sync отклонил (длинное?) → async")
            return await asyncio.to_thread(_sber_async_recognize_sync, voice_data, token)
        raise

IDEAS_PROMPT = """Ты — ассистент по структурированию идей. На входе — расшифровка голосовой заметки.

🎯 ГЛАВНОЕ ПРАВИЛО: разделяй по СУТИ, а не по предложениям.
- Если в речи описан ОДИН проект/концепция/идея, а дальше раскрываются её части/функции/детали — это ОДНА идея с подпунктами. У объекта будет поле sub_points = ["...","..."].
- Если в речи перечислены НЕЗАВИСИМЫЕ задачи/идеи разных тем (без общего предмета) — верни массив из нескольких объектов.

Признаки ОДНОЙ идеи с подпунктами:
- общий предмет (платформа, сервис, фича, проект, событие);
- части дополняют друг друга и относятся к этому предмету;
- слова-маркеры: «реализовать функцию выбора», «добавить опцию», «также нужно», «и ещё», «причём», «при этом».
Пример: «Нужна платформа-посредник между заказчиками и таксистами. Должен быть выбор маршрута с ценой. Доп. услуги: платная дорога, опции. Аукцион между водителями.» — это ОДНА идея «Платформа-посредник» с 3 подпунктами.

Признаки РАЗНЫХ идей:
- разные сферы (например, маркетинг + личное + покупка);
- между ними нет логической связи;
- слова-маркеры: «и ещё», «отдельно», «кстати», смена темы.

Верни ТОЛЬКО JSON-массив:
[{"text": "главная формулировка идеи в инфинитиве", "sub_points": ["подпункт 1","подпункт 2"], "tags": ["тег1","тег2","тег3"]}]

sub_points — ОПЦИОНАЛЬНОЕ поле (массив строк). Заполняй ТОЛЬКО если идея с раскрытием. Если идея цельная без раскрытия — sub_points можно опустить или поставить [].

Правила тегов (1–4 уместных):
- Приоритет: высокий / средний / низкий
- Сфера: маркетинг / продажи / финансы / клиенты / соцсети / контент / обучение / поездки / личное
- Тип: задача / идея / гипотеза / встреча / звонок / покупка
- Срочность: сегодня / на неделе / без срока

Если идея явно одна — верни массив из ОДНОГО объекта. НЕ придумывай идей и подпунктов, которых нет в речи. ТОЛЬКО JSON."""

async def _process_ideas_text(msg, uid, transcript: str):
    w = await msg.answer(text="Раскладываю на идеи и создаю sub-страницы в Notion...")
    try:
        r = claude.messages.create(
            model=CLAUDE_MODEL, max_tokens=2000,
            system=IDEAS_PROMPT,
            messages=[{"role":"user","content": transcript}],
        )
        raw = r.content[0].text.strip()
        if raw.startswith("```"):
            raw = raw.split("\n",1)[1] if "\n" in raw else raw[3:]
            raw = raw.rsplit("```",1)[0]
        ideas = json.loads(raw)
        if not isinstance(ideas, list): ideas = [ideas]
        ideas = [i for i in ideas if isinstance(i, dict) and (i.get("text") or "").strip()]
        if not ideas:
            await w.message.edit(text="Не разобрал идей. Попробуй ещё раз — говори чуть конкретнее."); return
        parent = await asyncio.to_thread(_ideas_parent_id)
        if not parent:
            await w.message.edit(text="Notion не настроен (нет NOTION_PARENT_PAGE_ID)."); return
        results = []
        failed = []
        for idea in ideas:
            text = idea["text"].strip()
            tags = idea.get("tags") or []
            sub_points = [s.strip() for s in (idea.get("sub_points") or []) if isinstance(s, str) and s.strip()]
            try:
                url = await asyncio.to_thread(_create_notion_idea_subpage, parent, text, tags, transcript, sub_points)
                if url:
                    icon = "💡"
                    for t in tags:
                        if t.lower() in IDEA_ICONS: icon = IDEA_ICONS[t.lower()]; break
                    results.append((icon, text, url, tags, sub_points))
            except Exception as e:
                logger.error(f"Idea subpage create: {e}"); failed.append(text[:50])
        if not results:
            await w.message.edit(text="Не удалось создать страницы в Notion. " + (f"Ошибки: {failed[0]}" if failed else "")); return
        lines = [f"💡 <b>Создано идей: {len(results)}</b>\n"]
        for icon, text, url, tags, sub_points in results[:10]:
            tag_s = " " + " ".join(f"<code>#{t}</code>" for t in tags[:3]) if tags else ""
            lines.append(f'{icon} <a href="{url}">{text[:80]}</a>{tag_s}')
            for sp in sub_points[:5]:
                lines.append(f"   • {sp[:80]}")
            if len(sub_points) > 5:
                lines.append(f"   <i>…и ещё {len(sub_points)-5} подпунктов</i>")
        if len(results) > 10:
            lines.append(f"\n<i>…и ещё {len(results)-10}. Полный список — кнопка «📋 Все идеи».</i>")
        if failed:
            lines.append(f"\n⚠️ Не создано: {len(failed)}")
        # Сохраняем последние идеи в state — нужно для callback'а «🚀 В Lovable»
        recent = []
        for icon, text, url, tags, sub_points in results[:10]:
            recent.append({"text": text, "tags": tags, "sub_points": sub_points})
        if uid not in user_states: user_states[uid] = {"table": "ideas"}
        user_states[uid]["_recent_ideas"] = recent
        # Кнопки «🚀 В Lovable #N» — по одной на идею (ограничим 5, чтобы не флудить)
        kb_rows = []
        for i, idea in enumerate(recent[:5]):
            label = f"🚀 #{i+1} в Lovable: {idea['text'][:35]}"
            kb_rows.append([CallbackButton(text=label, payload=f"lov_{i}")])
        kb = _make_kb(kb_rows) if kb_rows else None
        await w.message.edit(text="\n".join(lines), attachments=[kb])
    except json.JSONDecodeError:
        await w.message.edit(text="Не смог разложить на идеи. Попробуй ещё раз.")
    except Exception as e:
        logger.error(f"Ideas: {e}")
        err = str(e)[:150].replace("<","&lt;").replace(">","&gt;")
        await w.message.edit(text=f"Ошибка: {err}")

LOVABLE_BASE_TEMPLATE = """Стек: React + TypeScript + Tailwind CSS. Mobile-first, полная адаптация под смартфон (тап-зоны ≥44 px, читаемый шрифт, отступы не наезжают друг на друга).

Структура страницы:
1) Hero с чётким оффером и CTA выше первого скролла
2) Блок «как это работает» в 3 шага
3) Социальное доказательство (отзывы / цифры / факты)
4) Форма заявки (см. ниже — критично для 152-ФЗ)
5) Контакты-кнопки: WhatsApp, Telegram, MAX (max.ru), телефон
6) Футер с реквизитами

Форма заявки — ОБЯЗАТЕЛЬНО по российскому 152-ФЗ «О персональных данных»:
- Минимум полей: имя + телефон. Email — ТОЛЬКО если реально нужен.
- Чекбокс «Согласен на обработку персональных данных» — по умолчанию ВЫКЛЮЧЕН, обязательный для отправки.
- Рядом с чекбоксом ссылка «Политика конфиденциальности» — сгенерируй также страницу-заглушку с текстом политики.
- Под формой 1-2 строкой указание ЦЕЛИ обработки данных (например: «связаться с вами по заявке, не передаём третьим лицам»).
- Обязательные поля помечены звёздочкой *.
- Валидация: маска телефона +7 (___) ___-__-__, имя — буквы и пробелы, не пустое.
- Без бэкенда: кнопка «Отправить» пишет данные в console.log и показывает приятное сообщение «Спасибо, скоро свяжемся».

Дизайн:
- Мягкие пастельные цвета (1 основной + 1 акцентный + нейтралка), без кислотных оттенков.
- Плавные градиенты, мягкие переходы между секциями (без резких границ).
- Скруглённые углы (rounded-2xl), мягкие тени (shadow-lg / shadow-xl).
- Типографика: Inter или Space Grotesk, крупные заголовки, читаемый body 16-18 px.
- Поддержка тёмной темы (toggle в шапке).

Дофаминовые анимации кнопок (важно):
- Hover: scale 1.02-1.05 + плавный gradient-shift + лёгкий glow.
- Active/click: scale 0.95 с ease-out + ripple-эффект.
- Иконки CTA — лёгкое «дыхание» (subtle scale loop).
- Все transitions 200-300 ms с cubic-bezier для приятной кривой движения.

Технически:
- SEO-метатеги (title, description, OG-image заглушка, viewport).
- Семантический HTML (header/main/section/article/footer).
- ARIA-лейблы, контраст AA, focus-стейты на всех интерактивных элементах.
- Alt-тексты для изображений, lazy loading.

Язык контента: русский (если сама идея не на другом).
Контент-заглушки: осмысленные тексты по теме идеи — НЕ Lorem ipsum.

Сделай рабочий MVP."""


@router.message_callback(F.payload.startswith("lov_"))
async def cb_lovable(event: MessageCallback):
    cb = event.callback
    msg = event.message
    """Формирует промпт для Lovable из выбранной идеи и присылает его юзеру
    готовым к копи-пасту в @lovable_telegram_bot."""
    uid = cb.user.user_id
    try:
        idx = int(cb.payload[4:])
    except Exception:
        return await event.bot.send_callback(cb.callback_id, notification=" ")
    ideas = user_states.get(uid, {}).get("_recent_ideas") or []
    if idx >= len(ideas):
        return await event.bot.send_callback(cb.callback_id, notification=" ")
    idea = ideas[idx]

    parts = ["Сделай мне сайт/прототип:", "", idea["text"]]
    if idea.get("sub_points"):
        parts.append("")
        parts.append("Реализуй следующие функции:")
        for sp in idea["sub_points"]:
            parts.append(f"- {sp}")
    parts.append("")
    parts.append(LOVABLE_BASE_TEMPLATE)
    prompt = "\n".join(parts)

    # Отправляем в моноширинном блоке — long-tap → Copy в Telegram удобно копирует
    msg_text = (
        "🚀 <b>Промпт готов для Lovable</b>\n\n"
        "1. Долго-тапни блок ниже → «Скопировать»\n"
        "2. Открой Lovable-бота кнопкой\n"
        "3. Вставь и отправь\n\n"
        f"<pre>{prompt}</pre>"
    )
    kb = _make_kb([
        [LinkButton(text="🚀 Открыть Lovable бот", url="https://telegram.me/lovable_telegram_bot")]
    ])
    await msg.answer(msg_text, attachments=[kb])
    await event.bot.send_callback(cb.callback_id, notification=" ")


@router.message_created(F.message)
async def handle_voice(event: MessageCreated):
    msg = event.message
    uid = msg.sender.user_id
    if not allowed(uid): return

    # Рефлексия: голосовое
    if uid in reflection_states and reflection_states[uid].get("step") == "waiting_input":
        await reflection_handle_voice(msg)
        return

    state = user_states.get(uid, {})
    table = state.get("table") if state else None

    w = await msg.answer(text="Расшифровываю голосовое...")
    try:
        transcript = await _transcribe_voice(msg)
    except Exception as e:
        logger.error(f"Voice transcribe: {e}")
        err = str(e)[:200].replace("<","&lt;").replace(">","&gt;")
        await w.message.edit(text=
            "Не получилось расшифровать голосовое.\n\n"
            f"<i>Тех. деталь: {err}</i>"
        )
        return

    bad = (not transcript) or any(p in transcript.lower()[:80]
                                  for p in ["не могу", "i cannot", "i'm unable", "не способ"])
    if bad:
        await w.message.edit(text="Не разобрал голосовое. Попробуй ещё раз или текстом.")
        return

    # Спец-флоу для идей и гидов — там расшифровка автоматически идёт дальше
    if table == "ideas":
        await w.message.edit(text=f"🎙 «{transcript[:120]}{'...' if len(transcript)>120 else ''}»")
        await _process_ideas_text(msg, uid, transcript)
        return
    if table == "guides":
        if uid not in guide_docs: guide_docs[uid] = []
        guide_docs[uid].append({"type":"text","text":f"[Голосовое]: {transcript}"})
        await w.message.edit(text=f"🎙 Расшифровано: «{transcript[:100]}{'...' if len(transcript)>100 else ''}»")
        await ask_more_guide(await msg.answer(text="Получил голосовое"), uid)
        return

    # Дневник питания: голос → расшифровка → распознать как описание еды
    if table == "nutrition" and nutrition_module and uid == NUTRITION_OWNER_USER_ID:
        await w.message.edit(text=f"🎙 «{transcript[:120]}{'...' if len(transcript)>120 else ''}»")
        fake = FakeMsg(msg, transcript)
        try:
            await nutrition_module.handle_text(fake)
        except Exception as e:
            logger.error(f"Nutrition voice: {e}")
            await msg.answer(text="Не получилось обработать голосовое в питании.")
        return

    # Финучёт (ДДС=1, КУДиР=2): голос идёт в batch_docs как текст-документ.
    # Дальше юзер жмёт «Обработать» — и работает тот же pipeline что для фото/чека.
    if table in (1, 2):
        if uid not in batch_docs: batch_docs[uid] = []
        today_str = datetime.date.today().strftime("%d.%m.%Y")
        voice_doc = (
            f"[ГОЛОСОВАЯ ЗАМЕТКА от пользователя — устное описание операции]\n"
            f"Текст речи: «{transcript}»\n"
            f"Сегодняшняя дата: {today_str} (используй её, если в речи дата не названа).\n"
            f"Извлеки сумму и краткое описание. Документальные поля "
            f"(номер пп, ФД, БИК, ИНН, реквизиты получателя) — null, "
            f"их нет в голосовом сообщении. doc_type='другое'."
        )
        batch_docs[uid].append({"type":"text","text":voice_doc})
        await w.message.edit(text=f"🎙 Расшифровано: «{transcript[:100]}{'...' if len(transcript)>100 else ''}»")
        await ask_more(await msg.answer(text="Получил голосовое"), uid)
        return

    # Режим путешествия — сохраняем голос как заметку-дневник к текущему путешествию.
    if table == "travel":
        try:
            diary, label = await save_travel_note(transcript)
            safe = diary.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            await w.message.edit(text=
                f"📓 Записал в заметки путешествия <b>{label}</b>:\n\n<code>{safe}</code>"
            )
        except Exception as e:
            logger.error(f"Travel note save: {e}")
            safe = transcript.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            await w.message.edit(text=
                f"🎙 <b>Распознано</b> <i>(нажми, чтобы скопировать)</i>:\n\n<code>{safe}</code>\n\n"
                f"<i>В заметки сохранить не удалось: {str(e)[:80]}</i>"
            )
        return

    # Везде остальное (туристы, задачи и т.д.) — показать текст копируемым блоком,
    # пользователь сам копирует или пересылает в нужный раздел.
    safe = transcript.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    await w.message.edit(text=
        f"🎙 <b>Распознано</b> <i>(нажми на текст, чтобы скопировать)</i>:\n\n"
        f"<code>{safe}</code>"
    )

