@router.message_callback(F.callback.payload == "guide_go")
async def cb_guide_go(event: MessageCallback):
    cb = event.callback
    msg = event.message
    uid = cb.user.user_id
    docs = guide_docs.get(uid, [])
    if not docs: return await event.bot.send_callback(cb.callback_id, notification=" ")
    await msg.edit(text="🗺 Анализирую информацию о гиде...")
    try:
        content = []
        for doc in docs:
            if doc["type"] == "text": content.append({"type":"text","text":doc["text"]})
            elif doc["type"] == "document": content.append({"type":"document","source":{"type":"base64","media_type":doc["media_type"],"data":doc["data"]}})
            else: content.append({"type":"image","source":{"type":"base64","media_type":doc["media_type"],"data":doc["data"]}})
        content.append({"type":"text","text":"Извлеки информацию о гиде. JSON."})
        sp = GUIDE_SYSTEM_PROMPT_MULTI if len(docs) > 1 else GUIDE_SYSTEM_PROMPT
        r = claude.messages.create(model=CLAUDE_MODEL, max_tokens=1500, system=sp, messages=[{"role":"user","content":content}])
        await process_guide_result(cb.message, uid, r)
    except Exception as e:
        logger.error(f"Guide batch: {e}"); await msg.edit(text=f"Ошибка: {str(e)[:100]}. /start")
    await event.bot.send_callback(cb.callback_id, notification=" ")

async def process_guide_result(msg, uid, response):
    try:
        raw = response.content[0].text.strip()
        if raw.startswith("```"):
            raw = raw.split("\n",1)[1] if "\n" in raw else raw[3:]
            raw = raw.rsplit("```",1)[0]
        # Robust: модель иногда оборачивает JSON в текст вроде "Вот JSON: {...}"
        # Берём первый '{' или '[' и парный закрывающий — заведомо валидный JSON-блок.
        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError:
            obj_start = raw.find("{")
            arr_start = raw.find("[")
            starts = [s for s in (obj_start, arr_start) if s >= 0]
            if not starts:
                raise
            start = min(starts)
            end = max(raw.rfind("}"), raw.rfind("]"))
            if end <= start:
                raise
            parsed = json.loads(raw[start:end+1])
        guides = parsed if isinstance(parsed, list) else [parsed]
        processed = []
        for g in guides:
            processed.append({
                "country": (g.get("country","") or "").upper(),
                "city": g.get("city","") or "",
                "guide_name": g.get("guide_name","") or "",
                "contacts": g.get("contacts","") or "",
                "description": g.get("description","") or "",
            })
        guide_docs.pop(uid, None)
        user_states[uid] = {"table":"guides","guide_ops":processed,"guide_idx":0,"step":"guide_preview"}
        await msg.message.edit(text=f"🗺 Распознано: {len(processed)} гид(ов)")
        await show_guide(msg, uid)
    except json.JSONDecodeError:
        try: logger.error(f"Guide JSON parse failed. Raw: {response.content[0].text[:500]!r}")
        except Exception: pass
        await msg.message.edit(text="Не распознал. /start")
    except Exception as e: logger.error(f"Guide process: {e}"); await msg.message.edit(text="Ошибка. /start")

async def show_guide(msg, uid):
    state = user_states[uid]
    guides = state["guide_ops"]; idx = state["guide_idx"]; g = guides[idx]; total = len(guides)
    header = f"<b>🗺 Гид {idx+1}/{total}</b>\n\n" if total > 1 else "<b>🗺 Гид</b>\n\n"
    lines = []
    if g.get("country"): lines.append(f"Страна: {g['country']}")
    if g.get("city"): lines.append(f"Город: {g['city']}")
    if g.get("guide_name"): lines.append(f"  Гид: {g['guide_name']}")
    if g.get("contacts"): lines.append(f"  тел: Контакты: {g['contacts']}")
    if g.get("description"): lines.append(f"  Описание: {g['description']}")
    preview = "\n".join(lines) or "Нет данных"
    kb_rows = [
        [CallbackButton(text="✅ Записать", payload="guide_save")],
        [CallbackButton(text="Изм. страну", payload="ge_country"),
         CallbackButton(text="Изм. город", payload="ge_city")],
        [CallbackButton(text="Изм. имя", payload="ge_name"),
         CallbackButton(text="Изм. контакты", payload="ge_contacts")],
        [CallbackButton(text="Изм. описание", payload="ge_desc")],
        RESET_ROW,
    ]
    await msg.answer(text=f"{header}{preview}", attachments=[_make_kb(kb_rows)])

