# Сохранение гида (с проверкой дублей + сортировка по стране)
@router.message_callback(F.callback.payload == "guide_save")
async def cb_guide_save(event: MessageCallback):
    cb = event.callback
    msg = event.message
    uid = cb.user.user_id
    state = user_states.get(uid)
    if not state or not state.get("guide_ops") or "guide_idx" not in state: return await event.bot.send_callback(cb.callback_id, notification=" ")
    g = state["guide_ops"][state["guide_idx"]]
    try:
        sheet = gc.open_by_key(SPREADSHEET_ID_GUIDES).sheet1
        all_rows = sheet.get_all_values()

        # Проверка дублей — ТОЛЬКО по контактам (телефон)
        guide_contacts_lower = (g.get("contacts","") or "").lower().strip()
        new_phones = set(re.findall(r'\d{7,}', guide_contacts_lower))
        duplicate_row = None

        for i, row in enumerate(all_rows):
            if i == 0: continue
            existing_contacts = (row[3] if len(row) > 3 else "").lower()
            existing_phones = set(re.findall(r'\d{7,}', existing_contacts))

            # Совпадение только по телефону
            if new_phones and existing_phones and new_phones & existing_phones:
                duplicate_row = i + 1; break

        if duplicate_row:
            existing = all_rows[duplicate_row - 1]
            existing_info = f"{existing[0] if len(existing)>0 else ''}, {existing[1] if len(existing)>1 else ''}, {existing[2] if len(existing)>2 else ''}"
            user_states[uid]["_dup_row"] = duplicate_row
            kb = _make_kb([
                [CallbackButton(text="Дополнить информацию", payload="guide_supplement_dup")],
                [CallbackButton(text="Заменить полностью", payload="guide_update_dup")],
                [CallbackButton(text="Добавить как нового", payload="guide_force_save")],
                [CallbackButton(text="Пропустить", payload="guide_skip_dup")],
                RESET_ROW,
            ])
            await msg.answer(text=f"<b>Похожий гид уже есть:</b>\n{existing_info}\n\nЧто сделать?", attachments=[kb])
            await event.bot.send_callback(cb.callback_id, notification=" ")
            return

        # Нет дубля — вставляем с сортировкой по стране
        insert_guide_sorted(sheet, all_rows, g)
        await msg.edit(text=((msg.body.text or "") if msg.body else "") + "\n\n✅ Записано в базу гидов!")
        await advance_guide(cb.message, uid, state)
        await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"Guide write: {e}"); await event.bot.send_callback(cb.callback_id, notification=" ")

@router.message_callback(F.callback.payload == "guide_update_dup")
async def cb_guide_update_dup(event: MessageCallback):
    cb = event.callback
    msg = event.message
    """Заменить существующую запись гида полностью."""
    uid = cb.user.user_id
    state = user_states.get(uid)
    if not state or not state.get("guide_ops") or "guide_idx" not in state: return await event.bot.send_callback(cb.callback_id, notification=" ")
    g = state["guide_ops"][state["guide_idx"]]
    dup_row = state.get("_dup_row")
    if not dup_row: return await event.bot.send_callback(cb.callback_id, notification=" ")
    try:
        sheet = gc.open_by_key(SPREADSHEET_ID_GUIDES).sheet1
        row_data = [g.get("country","").upper(), g.get("city",""), g.get("guide_name",""),
                    safe_phone(g.get("contacts","")), g.get("description","")]
        for col_idx, val in enumerate(row_data):
            if val:
                sheet.update_cell(dup_row, col_idx + 1, str(val))
        state.pop("_dup_row", None)
        await msg.edit(text="Гид обновлён (заменён).")
        await advance_guide(cb.message, uid, state); await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"Guide update: {e}"); await event.bot.send_callback(cb.callback_id, notification=" ")

@router.message_callback(F.callback.payload == "guide_supplement_dup")
async def cb_guide_supplement(event: MessageCallback):
    cb = event.callback
    msg = event.message
    """Дополнить существующую запись — добавить новые данные, не удаляя старые."""
    uid = cb.user.user_id
    state = user_states.get(uid)
    if not state or not state.get("guide_ops") or "guide_idx" not in state: return await event.bot.send_callback(cb.callback_id, notification=" ")
    g = state["guide_ops"][state["guide_idx"]]
    dup_row = state.get("_dup_row")
    if not dup_row: return await event.bot.send_callback(cb.callback_id, notification=" ")
    try:
        sheet = gc.open_by_key(SPREADSHEET_ID_GUIDES).sheet1
        existing = sheet.row_values(dup_row)
        # Дополняем каждое поле
        new_data = [g.get("country","").upper(), g.get("city",""), g.get("guide_name",""),
                    g.get("contacts",""), g.get("description","")]
        for col_idx, new_val in enumerate(new_data):
            if not new_val: continue
            old_val = existing[col_idx] if col_idx < len(existing) else ""
            if not old_val:
                # Пустое — просто записываем
                sheet.update_cell(dup_row, col_idx + 1, safe_phone(new_val) if col_idx == 3 else str(new_val))
            elif new_val.lower().strip() != old_val.lower().strip():
                if col_idx == 1:  # город — добавляем через запятую
                    if new_val.lower() not in old_val.lower():
                        sheet.update_cell(dup_row, col_idx + 1, f"{old_val}, {new_val}")
                elif col_idx == 3:  # контакты — добавляем новые
                    if new_val.lower() not in old_val.lower():
                        sheet.update_cell(dup_row, col_idx + 1, safe_phone(f"{old_val}, {new_val}"))
                elif col_idx == 4:  # описание — добавляем в конец
                    sheet.update_cell(dup_row, col_idx + 1, f"{old_val}\n{new_val}")
        state.pop("_dup_row", None)
        await msg.edit(text="Информация дополнена!")
        await advance_guide(cb.message, uid, state); await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"Guide supplement: {e}"); await event.bot.send_callback(cb.callback_id, notification=" ")

