def insert_guide_sorted(sheet, all_rows, g):
    """Вставить гида в таблицу, сортируя по стране (столбец A) алфавитно."""
    country = (g.get("country","") or "").upper()
    contacts_raw = g.get("contacts","") or ""
    row_data = [country, g.get("city",""), g.get("guide_name",""),
                safe_phone(contacts_raw), g.get("description","")]
    row_data = [str(v) if v is not None else "" for v in row_data]

    # Ищем куда вставить — после последней строки с такой же страной,
    # или в алфавитном порядке между странами
    insert_at = None
    last_same_country = None

    for i, row in enumerate(all_rows):
        if i == 0: continue  # заголовок
        row_country = (row[0] if len(row) > 0 else "").upper().strip()
        if row_country == country:
            last_same_country = i + 1  # gspread нумерация с 1
        elif last_same_country is not None:
            # Мы вышли из блока этой страны
            break
        elif not last_same_country and row_country > country and row_country:
            # Страна идёт по алфавиту позже — вставим перед ней
            insert_at = i + 1
            break

    if last_same_country:
        sheet.insert_row(row_data, last_same_country + 1, value_input_option="USER_ENTERED")
    elif insert_at:
        sheet.insert_row(row_data, insert_at, value_input_option="USER_ENTERED")
    else:
        sheet.append_row(row_data, value_input_option="USER_ENTERED")

async def advance_guide(msg, uid, state):
    """Переход к следующему гиду или завершение."""
    state["guide_idx"] += 1
    if state["guide_idx"] < len(state["guide_ops"]):
        state["step"] = "guide_preview"
        await show_guide(msg, uid)
    else:
        user_states.pop(uid, None)
        kb = _make_kb([
            [CallbackButton(text="Ещё гид", payload="table_guides")],
            [CallbackButton(text="Новая операция", payload="reset")]])
        await msg.answer(text="Все гиды записаны!", attachments=[kb])

