@router.message_callback(F.callback.payload == "batch_go")
async def cb_go(event: MessageCallback):
    cb = event.callback
    msg = event.message
    uid = cb.user.user_id
    docs = batch_docs.get(uid, [])
    if not docs: return await event.bot.send_callback(cb.callback_id, notification=" ")
    await msg.edit(text="Анализирую...")
    try:
        content = []
        for doc in docs:
            if doc["type"] == "text": content.append({"type":"text","text":doc["text"]})
            elif doc["type"] == "document": content.append({"type":"document","source":{"type":"base64","media_type":doc["media_type"],"data":doc["data"]}})
            else: content.append({"type":"image","source":{"type":"base64","media_type":doc["media_type"],"data":doc["data"]}})
        table = user_states.get(uid, {}).get("table", 1)
        if table == 2:
            content.append({"type":"text","text":"Собери сводную запись по заявке. JSON."})
            r = claude.messages.create(model=CLAUDE_MODEL, max_tokens=1500, system=KUDIR_PROMPT, messages=[{"role":"user","content":content}])
            await process_kudir(cb.message, uid, r)
        else:
            prompt = "Распознай данные и верни JSON."
            if len(docs) > 1: prompt = f"{len(docs)} документа по одной заявке. Общие данные подставь во все. JSON-массив."
            content.append({"type":"text","text":prompt})
            sp = SYSTEM_PROMPT_BATCH if len(docs) > 1 else SYSTEM_PROMPT
            r = claude.messages.create(model=CLAUDE_MODEL, max_tokens=1500, system=sp, messages=[{"role":"user","content":content}])
            await process_result(cb.message, uid, r)
    except Exception as e:
        logger.error(f"Batch: {e}"); await msg.edit(text=f"Ошибка: {str(e)[:100]}. /start")
    await event.bot.send_callback(cb.callback_id, notification=" ")

# ==================== ОБРАБОТКА РЕЗУЛЬТАТА ====================

def clean_order_number(raw):
    """Извлекает ПЕРВЫЙ номер заявки туроператора из текста.
    Поддерживает коды (KM155961, CBR60501AD) и числовые номера (5591161)."""
    if not raw:
        return ""
    raw = str(raw).strip()
    # Берём ТОЛЬКО первое совпадение в порядке как в тексте
    # 1. Буквенно-цифровой код: 2+ букв + цифры (KM155961, CBR60501AD, MCC61026VA)
    m = re.search(r'\b[A-ZА-Я]{2,}\d[A-Z0-9А-Я]*\b', raw, re.IGNORECASE)
    if m:
        return m.group(0)
    # 2. Числовой код 5+ цифр (5591161), но не дата
    m = re.search(r'(?<![.\d])\b\d{5,}\b(?![.\d])', raw)
    if m:
        return m.group(0)
    return ""

async def process_result(msg, uid, response):
    try:
        raw = response.content[0].text.strip()
        if raw.startswith("```"):
            raw = raw.split("\n",1)[1] if "\n" in raw else raw[3:]
            raw = raw.rsplit("```",1)[0]
        raw = raw.strip()
        if not raw.startswith(("{", "[")):
            m = re.search(r'(\{[\s\S]*\}|\[[\s\S]*\])', raw)
            if m: raw = m.group(1)
        parsed = json.loads(raw)
        ops = parsed if isinstance(parsed, list) else [parsed]
        # Сбор «общих» значений по всему набору операций. Если модель заполнила поле
        # хоть в одной операции — протянем во все, где оно пустое.
        def _first_nonempty(field):
            for o in ops:
                v = o.get(field)
                if v not in (None, "", 0): return v
            return ""
        shared_order = clean_order_number(_first_nonempty("order_number"))
        shared_crm_order = _first_nonempty("crm_order_number")
        shared_crm_date = _first_nonempty("crm_creation_date")
        shared_month = _first_nonempty("tour_month")
        shared_year = _first_nonempty("tour_year")
        shared_op_raw = _first_nonempty("tour_operator_raw")
        processed = []
        for op in ops:
            raw_op = op.get("tour_operator_raw","") or shared_op_raw or ""
            detected = detect_operator(raw_op)
            doc_type = op.get("doc_type","") or ""
            is_refund = op.get("is_refund", False)
            is_incoming = bool(op.get("is_incoming", False))
            # Чек по умолчанию входящий (доход от клиента)
            if not is_incoming and "чек" in doc_type.lower() and not is_refund:
                is_incoming = True
            bank_name = op.get("bank_name") or ""

            # Bug 4: Чек возврата — автостатья "04. Прочие расходы. Возврат"
            if is_refund or "возврат" in doc_type.lower():
                article = "04. Прочие расходы. Возврат"
            else:
                article = auto_article(doc_type, detected, is_incoming)

            amount = op.get("amount","") or ""
            if article:
                if is_refund or "возврат" in doc_type.lower():
                    # Возврат — сумма всегда отрицательная
                    try: amount = -abs(float(str(amount).replace(",",".").replace(" ","")))
                    except Exception: pass
                else:
                    amount = apply_sign(amount, article)

            note = format_note(op.get("note",""), op.get("note_type",""))

            # Bug 2: Скрин СБП — в примечание "по корпоративной карте СБП"
            if doc_type.lower() in ("сбп",):
                note = "по корпоративной карте СБП"

            # Bug 5: Определение банка из скрина перевода — записать в account
            account = "расчетный счет"
            if bank_name:
                # Нормализуем название банка
                bn = bank_name.lower()
                if "сбер" in bn: account = "Сбербанк"
                elif "тиньк" in bn or "tinkoff" in bn or "т-банк" in bn or "t-bank" in bn: account = "Тинькофф"
                elif "точка" in bn or "tochka" in bn: account = "Точка"
                elif "альфа" in bn or "alfa" in bn: account = "Альфа-Банк"
                elif "втб" in bn or "vtb" in bn: account = "ВТБ"
                elif "freedom" in bn or "фридом" in bn: account = "Freedom"
                elif "цифра" in bn or "cifra" in bn: account = "Цифра"
                else: account = bank_name

            # Номер заявки: если у этой операции пусто, но есть общий — берём общий.
            raw_order = op.get("order_number","") or ""
            order_number = clean_order_number(raw_order) or shared_order

            comment = op.get("comment","") or ""
            # Для исходящих — выкинуть упоминания нашего ИП (Малинкиной) из comment:
            # туда должен попасть ТУРИСТ, не плательщик.
            if not is_incoming and comment:
                comment = re.sub(
                    r'(?:ИП\s+)?Малинкина(?:\s+Анастасия(?:\s+Александровна)?)?|'
                    r'А\.?\s*А\.?\s*Малинкина|Анастасия\s+Александровна',
                    '', comment, flags=re.IGNORECASE
                )
                comment = re.sub(r'\s*,\s*,', ',', comment)
                comment = comment.strip(' ,;.-')
            # Достроить «, договор XXX от ДД.ММ.ГГГГ» из CRM, если модель не вписала.
            # Если у этой операции пусто — берём общий из других операций набора.
            crm_order = op.get("crm_order_number") or shared_crm_order or ""
            crm_date = op.get("crm_creation_date") or shared_crm_date or ""
            if crm_order and crm_date:
                contract_str = f"{crm_order} от {crm_date}"
                if contract_str not in comment:
                    comment = f"{comment}, договор {contract_str}" if comment else f"Договор {contract_str}"

            month = op.get("tour_month","") or shared_month or ""
            year = op.get("tour_year","") or shared_year or ""
            # Если месяц/год не распознан — подставляем текущие
            if not month and not year:
                now = datetime.datetime.now()
                month = ("январь","февраль","март","апрель","май","июнь",
                         "июль","август","сентябрь","октябрь","ноябрь","декабрь")[now.month - 1]
                year = str(now.year)

            processed.append({
                "date":op.get("date","") or "","payer":"Малинкина А.А.","account":account,
                "amount":amount,"article":article,
                "comment":comment,"order_number":order_number,
                "month":month,"year":year,
                "tour_operator":detected,"note":note,
                "_raw_op":raw_op,"_doc_type":doc_type,
            })
        batch_docs.pop(uid, None)
        user_states[uid] = {"table":1,"operations":processed,"current_op":0,"step":"preview"}
        await msg.message.edit(text=f"Распознано: {len(processed)} операций")
        await show_op(msg, uid)
    except json.JSONDecodeError: await msg.message.edit(text="Не удалось распознать. /start")
    except Exception as e: logger.error(f"Process: {e}"); await msg.message.edit(text="Ошибка. /start")

async def show_op(msg, uid):
    state = user_states[uid]
    ops = state["operations"]; idx = state["current_op"]; d = ops[idx]; total = len(ops)
    preview = fmt(d)
    header = f"<b>Операция {idx+1}/{total}</b>\n\n" if total > 1 else ""
    raw_op = d.pop("_raw_op",""); doc_type = d.pop("_doc_type","")
    note = ""
    if raw_op and d.get("tour_operator"): note = f"\n<i>{raw_op} = {d['tour_operator']}</i>"
    if doc_type: note += f"\n<i>Тип: {doc_type}</i>"
    kb_rows = []
    if d.get("article"):
        kb_rows.append([CallbackButton(text="Записать", payload="final_confirm")])
        kb_rows.append([CallbackButton(text="Изм. статью", payload="edit_article")])
    else:
        kb_rows.append([CallbackButton(text="Выбрать статью", payload="edit_article")])
    kb_rows.append([CallbackButton(text="Изм. комментарий", payload="edit_comment"),
                    CallbackButton(text="Изм. сумму", payload="edit_amount")])
    kb_rows.append([CallbackButton(text="Изм. заявку", payload="edit_order"),
                    CallbackButton(text="Изм. примечание", payload="edit_note")])
    kb_rows.append([CallbackButton(text="Месяц/год тура", payload="edit_monthyear"),
                    CallbackButton(text="Изм. счёт", payload="edit_account")])
    kb_rows.append([CallbackButton(text="Изм. дату", payload="edit_date"),
                    CallbackButton(text="Изм. туроператора", payload="edit_operator")])
    kb_rows.append(RESET_ROW)
    await msg.answer(text=f"{header}{preview}{note}", attachments=[_make_kb(kb_rows)])

