# ==================== ТЕКСТОВЫЙ ВВОД ====================

async def handle_input(event: MessageCreated):
    msg = event.message
    uid = msg.sender.user_id
    state = user_states.get(uid)
    if not state: return
    step = state.get("step")
    if not step: return
    text = msg.body.text.strip()

    # Агент — текстовый ввод
    if step == "agent_learn":
        await _agent_process_file(msg, uid, [{"text": text}], image_bytes=None)
        return
    if step == "agent_ask":
        await _agent_answer_question(msg, uid, text)
        return
    if step == "agent_draw":
        w = await msg.answer(text="🎨 Рисую...")
        try:
            img_bytes = await _gemini_generate_image(text)
            if img_bytes:
                await msg.answer(text=" ", attachments=[InputMediaBuffer(buffer=img_bytes, filename="image.png", type="image")])
                await w.delete()
            else:
                await w.message.edit(text="❌ Не удалось сгенерировать изображение. Попробуй другой запрос.")
        except Exception as e:
            logger.error(f"Agent draw: {e}")
            await w.message.edit(text=f"❌ Ошибка: {str(e)[:150]}")
        return

    # Рецепты — текстовый ввод
    if step == "recipe_wait":
        gemini_parts = [{"text": text}]
        await _recipe_process_file(msg, uid, gemini_parts, image_bytes=None)
        return

    # Поиск гидов
    if step == "guide_search":
        user_states.pop(uid, None)
        await search_guides(msg, text)
        return

    # Гиды — редактирование полей
    if step.startswith("guide_"):
        guides = state.get("guide_ops")
        if not guides: return
        g = guides[state.get("guide_idx", 0)]
        if step == "guide_country": g["country"] = text.upper()
        elif step == "guide_city": g["city"] = text
        elif step == "guide_name": g["guide_name"] = text
        elif step == "guide_contacts": g["contacts"] = text
        elif step == "guide_desc": g["description"] = text
        state["step"] = "guide_preview"
        await show_guide(msg, uid)
        return

    # КУДиР steps — handled separately, don't need "operations"
    if step.startswith("kudir_"):
        k = user_states[uid].get("kudir")
        if not k: return
        if step == "kudir_desc": k["description"] = text
        elif step == "kudir_income":
            k["income"] = text
            try: k["taxable"] = round(float(text.replace(",",".").replace(" ","")) - float(str(k.get("tour_payment",0) or 0).replace(",",".").replace(" ","")), 2)
            except Exception: pass
        elif step == "kudir_topay":
            k["tour_payment"] = text
            try: k["taxable"] = round(float(str(k.get("income",0) or 0).replace(",",".").replace(" ","")) - float(text.replace(",",".").replace(" ","")), 2)
            except Exception: pass
        elif step == "kudir_note": k["note"] = text
        elif step == "kudir_contract": k["contract"] = text
        elif step == "kudir_pp":
            clean = text.strip().lower().replace("пп", "").strip()
            k["payment_type"] = f"пп {clean}"
        state["step"] = "kudir_preview"
        await show_kudir(msg, uid)
        return

    # ДДС steps — need "operations"
    if not state.get("operations"): return
    cur = state["operations"][state["current_op"]]

    if step == "ask_commission":
        try:
            clean = re.sub(r"[^\d.,%]", "", text.replace(",",".").replace(" ",""))
            if "%" in clean:
                pct = float(clean.replace("%",""))
                base_amount = abs(float(str(state.get("_commission_base",{}).get("amount",0)).replace(",",".")))
                comm = round(base_amount * pct / 100, 2)
            else:
                comm = abs(float(clean))
            if comm > 0:
                base = state.get("_commission_base", cur)
                comm_row = [base.get("date",""),base.get("payer",""),base.get("account",""),
                    format_num(-comm),"03. Переменные расходы. Комиссия банка",base.get("comment",""),
                    base.get("order_number",""),base.get("month",""),base.get("year",""),
                    base.get("tour_operator",""),""]
                gc.open_by_key(SPREADSHEET_ID_1).sheet1.append_row([str(v) if v is not None else "" for v in comm_row], value_input_option="USER_ENTERED")
                await msg.answer(text=f"Комиссия -{comm} руб записана!")
            else: await msg.answer(text="Без комиссии.")
        except Exception: await msg.answer(text="Не понял. Без комиссии.")
        state.pop("_commission_base", None)
        await advance(msg, uid, state); return

    if step == "edit_date": cur["date"] = text
    elif step == "edit_comment": cur["comment"] = text
    elif step == "edit_amount":
        try:
            new_val = float(text.replace(",",".").replace(" ","").replace("−","-"))
        except Exception:
            new_val = text
        article = cur.get("article", "")
        cur["amount"] = apply_sign(new_val, article) if article else new_val
    elif step == "edit_account_custom":
        if state.get("operations"):
            state["operations"][state["current_op"]]["account"] = text
        state["step"] = "preview"; await show_op(msg, uid); return
    elif step == "edit_operator_custom":
        if state.get("operations"):
            state["operations"][state["current_op"]]["tour_operator"] = text
        state["step"] = "preview"; await show_op(msg, uid); return
    elif step == "edit_order": cur["order_number"] = text
    elif step == "edit_note": cur["note"] = text
    elif step == "edit_month":
        cur["month"] = text; state["step"] = "edit_year"
        await msg.answer(text="Год тура?"); return
    elif step == "edit_year": cur["year"] = text
    else: return
    state["step"] = "preview"; await show_op(msg, uid)

# ==================== ЗАПИСЬ ====================

@router.message_callback(F.callback.payload == "final_confirm")
async def cb_confirm(event: MessageCallback):
    cb = event.callback
    msg = event.message
    uid = cb.user.user_id
    state = user_states.get(uid)
    if not state or not state.get("operations") or "current_op" not in state: return await event.bot.send_callback(cb.callback_id, notification=" ")
    cur = state["operations"][state["current_op"]]
    try:
        row = [cur.get("date",""),cur.get("payer",""),cur.get("account",""),format_num(cur.get("amount","")),
               cur.get("article",""),cur.get("comment",""),cur.get("order_number",""),
               cur.get("month",""),cur.get("year",""),cur.get("tour_operator",""),cur.get("note","")]
        gc.open_by_key(SPREADSHEET_ID_1).sheet1.append_row([str(v) if v is not None else "" for v in row], value_input_option="USER_ENTERED")
        await msg.edit(text=((msg.body.text or "") if msg.body else "") + "\n\nЗаписано!")
        if cur.get("article","").startswith("01."):
            state["step"] = "ask_commission"
            state["_commission_base"] = cur.copy()
            kb = _make_kb([
                [CallbackButton(text="0,7%", payload="commission_pct"),
                 CallbackButton(text="1500 ₽", payload="commission_fixed")],
                [CallbackButton(text="Своя сумма", payload="commission_custom"),
                 CallbackButton(text="Нет комиссии", payload="commission_skip")],
                RESET_ROW])
            await msg.answer(text="Комиссия банка?", attachments=[kb])
        else: await advance(cb.message, uid, state)
        await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"Write: {e}"); await event.bot.send_callback(cb.callback_id, notification=" ")

