@router.message_callback(F.callback.payload == "kudir_confirm")
async def cb_kconfirm(event: MessageCallback):
    cb = event.callback
    msg = event.message
    uid = cb.user.user_id
    state = user_states.get(uid)
    if not state or not state.get("kudir"): return await event.bot.send_callback(cb.callback_id, notification=" ")
    d = state["kudir"]
    try:
        sheet = gc.open_by_key(SPREADSHEET_ID_2).sheet1
        row = [d.get("date_and_fd",""), d.get("description",""), format_num(d.get("income","")),
               format_num(d.get("tour_payment","")), d.get("payment_type",""), format_num(d.get("taxable","")),
               d.get("note",""), d.get("contract",""), d.get("status","")]
        row = [str(v) if v is not None else "" for v in row]
        sheet.append_row(row, value_input_option="USER_ENTERED")
        await msg.edit(text=((msg.body.text or "") if msg.body else "") + "\n\nЗаписано в буфер КУДиР!")
        # Сборная группа: остались записи в очереди — показываем следующую
        queue = state.get("kudir_queue") or []
        if queue:
            next_item, rest = queue[0], queue[1:]
            user_states[uid] = {
                "table": 2, "step": "kudir_preview",
                "kudir": next_item, "kudir_queue": rest,
            }
            await msg.answer(text=f"Следующая запись (осталось {1 + len(rest)}):")
            await show_kudir(cb.message, uid)
            return await event.bot.send_callback(cb.callback_id, notification=" ")
        # Очередь пуста — обычный завершающий экран
        user_states[uid] = {"table": 2}
        batch_docs[uid] = []
        await msg.answer(text="Готово! Скопируй строку из буфера в рабочую КУДиР.", attachments=[_make_kb([
            [CallbackButton(text="Новая операция", payload="reset")],
            [LinkButton(text="📋 Перейти в Таблицу 2 (КУДиР)", url="https://docs.google.com/spreadsheets/d/1paRk3fvQzwVwK7JyO6RIdjIJGrveBfhyMwD4UtkgJ7I/edit")],
            [LinkButton(text="📘 Таблица КУДиР (основная)", url="https://docs.google.com/spreadsheets/d/11gKJp3yzPpZjINT23gqYwy_F2MpP4qujPZzoSgFG2wg/edit")]
        ])])
        await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"KUDiR write: {e}"); await event.bot.send_callback(cb.callback_id, notification=" ")


# ==================== ТУРИСТЫ: ФУНКЦИИ ====================

def tourist_get_sheet():
    try:
        sp = gc.open_by_key(SPREADSHEET_ID_TOURISTS)
        return sp.sheet1
    except Exception as e:
        logger.error(f"Tourist sheet: {e}")
        return None

def tourist_get_all():
    sheet = tourist_get_sheet()
    if not sheet: return []
    rows = sheet.get_all_values()
    result = []
    for i, r in enumerate(rows):
        if i == 0: continue
        if not any((c or "").strip() for c in r): continue
        result.append({
            "row_num": i + 1,
            "date": r[0] if len(r) > 0 else "",
            "name": r[1] if len(r) > 1 else "",
            "phone": r[2] if len(r) > 2 else "",
            "destination": r[3] if len(r) > 3 else "",
            "dates": r[4] if len(r) > 4 else "",
            "budget": r[5] if len(r) > 5 else "",
            "group": r[6] if len(r) > 6 else "",
            "wishes": r[7] if len(r) > 7 else "",
            "status": r[8] if len(r) > 8 else "новый",
            "comments": r[9] if len(r) > 9 else "",
            "source": r[10] if len(r) > 10 else "",
        })
    return result

async def ask_more_tourist(msg, uid):
    n = len(tourist_docs.get(uid, []))
    kb = _make_kb([
        [CallbackButton(text=f"Обработать ({n})", payload="tourist_go")],
        [CallbackButton(text="Ещё", payload="tourist_more")],
        RESET_ROW,
    ])
    try: await msg.message.edit(text=f"Документов: {n}", attachments=[kb])
    except Exception: await msg.answer(text=f"Документов: {n}", attachments=[kb])

