@router.message_callback(F.callback.payload == "tourist_go")
async def cb_tourist_go(event: MessageCallback):
    cb = event.callback
    msg = event.message
    uid = cb.user.user_id
    docs = tourist_docs.get(uid, [])
    if not docs: return await event.bot.send_callback(cb.callback_id, notification=" ")
    await msg.edit(text="Анализирую...")
    try:
        content = []
        for doc in docs:
            if doc["type"] == "text": content.append({"type":"text","text":doc["text"]})
            elif doc["type"] == "document": content.append({"type":"document","source":{"type":"base64","media_type":doc["media_type"],"data":doc["data"]}})
            else: content.append({"type":"image","source":{"type":"base64","media_type":doc["media_type"],"data":doc["data"]}})
        content.append({"type":"text","text":"Извлеки данные о туристе. JSON."})
        sp = TOURIST_PROMPT_MULTI if len(docs) > 1 else TOURIST_PROMPT
        r = claude.messages.create(model=CLAUDE_MODEL, max_tokens=1500, system=sp, messages=[{"role":"user","content":content}])
        raw = r.content[0].text.strip()
        if raw.startswith("```"):
            raw = raw.split("\n",1)[1] if "\n" in raw else raw[3:]
            raw = raw.rsplit("```",1)[0]
        parsed = json.loads(raw)
        tourists = parsed if isinstance(parsed, list) else [parsed]
        tourist_docs.pop(uid, None)
        processed = []
        for t in tourists:
            processed.append({
                "date": datetime.datetime.now().strftime("%d.%m.%Y"),
                "name": t.get("name","") or "",
                "phone": t.get("phone","") or "",
                "destination": t.get("destination","") or "",
                "dates": t.get("dates","") or "",
                "budget": t.get("budget","") or "",
                "group": t.get("group","") or "",
                "wishes": t.get("wishes","") or "",
                "status": "новый",
                "comments": t.get("comments","") or "",
                "source": t.get("source","") or "",
            })
        user_states[uid] = {"table":"tourists","tourist_ops":processed,"tourist_idx":0,"step":"tourist_preview"}
        await msg.edit(text=f"Распознано: {len(processed)} турист(ов)")
        await show_tourist(cb.message, uid)
    except json.JSONDecodeError:
        await msg.edit(text="Не распознал. Попробуй снова.")
    except Exception as e:
        logger.error(f"Tourist: {e}"); await msg.edit(text=f"Ошибка: {str(e)[:100]}")
    await event.bot.send_callback(cb.callback_id, notification=" ")

async def show_tourist(msg, uid):
    state = user_states[uid]
    tourists = state["tourist_ops"]; idx = state["tourist_idx"]; t = tourists[idx]
    lines = []
    if t.get("name"): lines.append(f"<b>ФИО:</b> {t['name']}")
    if t.get("phone"): lines.append(f"<b>Контакт:</b> {t['phone']}")
    if t.get("destination"): lines.append(f"<b>Направление:</b> {t['destination']}")
    if t.get("dates"): lines.append(f"<b>Даты:</b> {t['dates']}")
    if t.get("budget"): lines.append(f"<b>Бюджет:</b> {t['budget']}")
    if t.get("group"): lines.append(f"<b>Состав:</b> {t['group']}")
    if t.get("wishes"): lines.append(f"<b>Пожелания:</b> {t['wishes']}")
    if t.get("comments"): lines.append(f"<b>Комментарии:</b> {t['comments']}")
    if t.get("source"): lines.append(f"<b>Источник:</b> {t['source']}")
    preview = "\n".join(lines) or "Нет данных"
    header = f"<b>Турист {idx+1}/{len(tourists)}</b>\n\n" if len(tourists) > 1 else "<b>Турист</b>\n\n"
    kb = _make_kb([
        [CallbackButton(text="Записать", payload="tourist_save")],
        [CallbackButton(text="Изм. ФИО", payload="te_name"),
         CallbackButton(text="Изм. контакт", payload="te_phone")],
        [CallbackButton(text="Изм. направление", payload="te_dest"),
         CallbackButton(text="Изм. пожелания", payload="te_wishes")],
        [CallbackButton(text="Изм. источник", payload="te_source")],
        RESET_ROW,
    ])
    await msg.answer(text=f"{header}{preview}", attachments=[kb])

