@router.message_callback(F.callback.payload == "tourist_save")
async def cb_tourist_save(event: MessageCallback):
    cb = event.callback
    msg = event.message
    uid = cb.user.user_id
    state = user_states.get(uid)
    if not state or not state.get("tourist_ops") or "tourist_idx" not in state: return await event.bot.send_callback(cb.callback_id, notification=" ")
    t = state["tourist_ops"][state["tourist_idx"]]
    try:
        sheet = tourist_get_sheet()
        # Проверка дублей по ФИО/телефону
        all_rows = sheet.get_all_values()
        name_lower = (t.get("name","") or "").lower().strip()
        phone_digits = set(re.findall(r'\d{7,}', t.get("phone","") or ""))
        dup_row = None
        for i, row in enumerate(all_rows):
            if i == 0: continue
            ex_name = (row[1] if len(row) > 1 else "").lower().strip()
            ex_phone = set(re.findall(r'\d{7,}', row[2] if len(row) > 2 else ""))
            if phone_digits and ex_phone and phone_digits & ex_phone:
                dup_row = i + 1; break
            if ex_name and name_lower and len(name_lower) > 3 and (ex_name == name_lower or name_lower in ex_name):
                dup_row = i + 1; break

        if dup_row:
            existing = all_rows[dup_row - 1]
            user_states[uid]["_dup_row"] = dup_row
            kb = _make_kb([
                [CallbackButton(text="Дополнить", payload="tourist_supplement")],
                [CallbackButton(text="Новая запись", payload="tourist_force_save")],
                [CallbackButton(text="Пропустить", payload="tourist_skip")],
            ])
            await msg.answer(text=f"<b>Турист уже есть:</b>\n{existing[1] if len(existing)>1 else ''}, {existing[3] if len(existing)>3 else ''}", attachments=[kb])
            await event.bot.send_callback(cb.callback_id, notification=" "); return

        row = [t.get("date",""), t.get("name",""), safe_phone(t.get("phone","")),
               t.get("destination",""), t.get("dates",""), t.get("budget",""),
               t.get("group",""), t.get("wishes",""), t.get("status","новый"), t.get("comments",""), t.get("source","")]
        sheet.append_row([str(v) if v else "" for v in row], value_input_option="USER_ENTERED")
        await msg.edit(text=((msg.body.text or "") if msg.body else "") + "\n\nЗаписано!")
        state["tourist_idx"] += 1
        if state["tourist_idx"] < len(state["tourist_ops"]):
            await show_tourist(cb.message, uid)
        else:
            user_states.pop(uid, None)
            await msg.answer(text="Все туристы записаны!", attachments=[KB_TOURISTS])
        await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"Tourist save: {e}"); await event.bot.send_callback(cb.callback_id, notification=" ")

@router.message_callback(F.callback.payload == "tourist_supplement")
async def cb_tourist_supplement(event: MessageCallback):
    cb = event.callback
    msg = event.message
    uid = cb.user.user_id
    state = user_states.get(uid)
    if not state or not state.get("tourist_ops") or "tourist_idx" not in state: return await event.bot.send_callback(cb.callback_id, notification=" ")
    t = state["tourist_ops"][state["tourist_idx"]]
    dup_row = state.get("_dup_row")
    if not dup_row: return await event.bot.send_callback(cb.callback_id, notification=" ")
    try:
        sheet = tourist_get_sheet()
        existing = sheet.row_values(dup_row)
        new_data = [t.get("date",""), t.get("name",""), t.get("phone",""), t.get("destination",""),
                    t.get("dates",""), t.get("budget",""), t.get("group",""), t.get("wishes",""),
                    "", t.get("comments","")]
        for col_idx, new_val in enumerate(new_data):
            if not new_val: continue
            old_val = existing[col_idx] if col_idx < len(existing) else ""
            if not old_val:
                sheet.update_cell(dup_row, col_idx + 1, safe_phone(new_val) if col_idx == 2 else str(new_val))
            elif new_val.lower().strip() != old_val.lower().strip():
                if col_idx in (7, 9):  # пожелания, комментарии — дополняем
                    sheet.update_cell(dup_row, col_idx + 1, f"{old_val}\n{new_val}")
                elif col_idx == 2:  # контакты
                    if new_val.lower() not in old_val.lower():
                        sheet.update_cell(dup_row, col_idx + 1, safe_phone(f"{old_val}, {new_val}"))
        state.pop("_dup_row", None)
        await msg.edit(text="Информация дополнена!")
        state["tourist_idx"] += 1
        if state["tourist_idx"] < len(state["tourist_ops"]):
            await show_tourist(cb.message, uid)
        else:
            user_states.pop(uid, None)
            await msg.answer(text="Готово!", attachments=[KB_TOURISTS])
        await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"Tourist supplement: {e}"); await event.bot.send_callback(cb.callback_id, notification=" ")

