@router.message_callback(F.payload.startswith("tfilter_"))
async def cb_tourist_filter(event: MessageCallback):
    cb = event.callback
    msg = event.message
    """Фильтр туристов по статусу."""
    status = cb.payload[8:]
    tourists = tourist_get_all()
    if status != "все":
        tourists = [t for t in tourists if t.get("status","").lower() == status.lower()]
    if not tourists:
        await msg.answer(text=f"Нет туристов со статусом «{status}».", attachments=[KB_TOURISTS])
        await event.bot.send_callback(cb.callback_id, notification=" "); return
    status_icons = {"новый":"⚪","в работе":"🔵","забронирован":"🟡","оплачен":"🟢","завершён":"✅"}
    lines = [f"<b>Туристы — {status}</b> ({len(tourists)})\n"]
    for t in tourists[-20:]:
        icon = status_icons.get(t.get("status",""), "⚪")
        name = t.get("name","—")
        dest = t.get("destination","")
        src = t.get("source","")
        line = f"{icon} <b>{name}</b>"
        if dest: line += f" → {dest}"
        if src: line += f" [{src}]"
        lines.append(line)
    # Добавляем кнопки смены статуса для каждого
    text = "\n".join(lines)
    text += "\n\nНапиши ФИО чтобы изменить статус."
    uid = cb.user.user_id
    user_states[uid] = {"table": "tourists", "step": "tourist_status_search"}
    await msg.answer(text=text, attachments=[KB_TOURISTS])
    await event.bot.send_callback(cb.callback_id, notification=" ")

async def tourist_portrait(msg, query):
    """Психологический портрет клиента."""
    tourists = tourist_get_all()
    q = query.lower().strip()
    found = [t for t in tourists if fuzzy_match(q, t.get("name","") + " " + t.get("phone",""))]
    if not found:
        await msg.answer(text=f"Турист «{query}» не найден.", attachments=[KB_TOURISTS]); return
    t = found[0]
    w = await msg.answer(text="Анализирую клиента...")
    client_data = "\n".join([f"{k}: {v}" for k, v in t.items() if v and k not in ("row_num","script")])
    try:
        r = claude.messages.create(
            model=CLAUDE_MODEL, max_tokens=3000,
            system=TOURIST_PORTRAIT_PROMPT.format(client_data=client_data),
            messages=[{"role":"user","content":f"Составь портрет клиента {t.get('name','')}"}]
        )
        portrait = md_to_html(r.content[0].text.strip())
        try: await w.delete()
        except Exception: pass
        # Разбиваем на части если длинный
        parts = []
        while len(portrait) > 4000:
            cut = portrait[:4000].rfind("\n")
            if cut < 2000: cut = 4000
            parts.append(portrait[:cut]); portrait = portrait[cut:]
        parts.append(portrait)
        for p in parts:
            await msg.answer(p, attachments=[KB_TOURISTS])
    except Exception as e:
        logger.error(f"Portrait: {e}")
        await w.message.edit(text=f"Ошибка: {str(e)[:100].replace('<','&lt;').replace('>','&gt;')}")

async def tourist_script(msg, query):
    """Скрипт продажи на основе завершённой сделки."""
    tourists = tourist_get_all()
    q = query.lower().strip()
    found = [t for t in tourists if fuzzy_match(q, t.get("name","") + " " + t.get("phone",""))]
    if not found:
        await msg.answer(text=f"Турист «{query}» не найден.", attachments=[KB_TOURISTS]); return
    t = found[0]
    st = (t.get("status","") or "").lower().strip().replace("ё","е")
    if st not in ("оплачен", "завершен", "завершён"):
        await msg.answer(text=f"Сделка с {t.get('name','')} ещё не завершена (статус: {t.get('status','')}).\nСкрипт доступен для завершённых/оплаченных сделок.", attachments=[KB_TOURISTS])
        return
    w = await msg.answer(text="Создаю скрипт...")
    client_data = "\n".join([f"{k}: {v}" for k, v in t.items() if v and k not in ("row_num","script")])
    try:
        r = claude.messages.create(
            model=CLAUDE_MODEL, max_tokens=1500,
            system=TOURIST_SCRIPT_PROMPT.format(client_data=client_data),
            messages=[{"role":"user","content":f"Создай скрипт продажи на основе сделки с {t.get('name','')}. Все шаблоны сообщений пиши ГОТОВЫМИ к копированию — с конкретными данными этого клиента (направление, даты, бюджет). Не используй [вставить] — пиши реальный текст."}]
        )
        script = r.content[0].text.strip()
        script_html = md_to_html(script)
        # Сохраняем скрипт в столбец L
        try:
            sheet = tourist_get_sheet()
            sheet.update_cell(t["row_num"], 12, script[:5000])
        except Exception as se:
            logger.error(f"Script save: {se}")
        try: await w.delete()
        except Exception: pass
        parts = []
        while len(script_html) > 4000:
            cut = script_html[:4000].rfind("\n")
            if cut < 2000: cut = 4000
            parts.append(script_html[:cut]); script_html = script_html[cut:]
        parts.append(script_html)
        for p in parts:
            await msg.answer(text=p)
        await msg.answer(text="Скрипт сохранён в таблицу.", attachments=[KB_TOURISTS])
    except Exception as e:
        logger.error(f"Script: {e}")
        await w.message.edit(text=f"Ошибка: {str(e)[:100].replace('<','&lt;').replace('>','&gt;')}")

async def tourist_edit_find(msg, uid, query):
    """Найти туриста для редактирования и показать кнопки полей."""
    tourists = tourist_get_all()
    q = query.lower().strip()
