async def tourist_edit_apply(msg, uid, new_value):
    """Применить редактирование поля туриста."""
    state = user_states.get(uid)
    if not state: return
    row_num = state.get("_edit_row")
    field = state.get("_edit_field")
    if not row_num or not field: return
    col = TOURIST_FIELD_COL.get(field)
    if not col: return
    try:
        sheet = tourist_get_sheet()
        # Для комментариев — дополняем, а не заменяем
        if field == "comments":
            existing = sheet.cell(row_num, col).value or ""
            if existing:
                new_value = f"{existing}\n{new_value}"
        sheet.update_cell(row_num, col, safe_phone(new_value) if field == "phone" else new_value)
        user_states.pop(uid, None)
        await msg.answer(text=f"Обновлено!", attachments=[KB_TOURISTS])
    except Exception as e:
        logger.error(f"Tourist edit: {e}")
        await msg.answer(text=f"Ошибка: {str(e)[:100].replace('<','&lt;').replace('>','&gt;')}")

# ==================== ТУРИСТЫ: АНАЛИЗ ЭКСПОРТА ЧАТА ====================

async def tourist_analyze_chat_export(msg, uid, text_content):
    """Анализ экспорта чата — извлечение данных туриста (1 вызов Claude)."""
    w = await msg.answer(text="Анализирую переписку...")
    if len(text_content) > 15000:
        text_content = text_content[:7000] + "\n...[пропущено]...\n" + text_content[-7000:]
    try:
        r1 = claude.messages.create(
            model=CLAUDE_MODEL, max_tokens=1000,
            system="""Из экспорта переписки извлеки данные туриста. Верни ТОЛЬКО JSON:
{"name":"ФИО","phone":"контакты","destination":"направление","dates":"даты","budget":"бюджет","group":"состав","wishes":"пожелания","source":"откуда пришёл","comments":"контекст"}
Нет данных — null. ТОЛЬКО JSON.""",
            messages=[{"role":"user","content":text_content[:8000]}]
        )
        raw1 = r1.content[0].text.strip()
        if raw1.startswith("```"): raw1 = raw1.split("\n",1)[1].rsplit("```",1)[0]
        tourist_data = json.loads(raw1)

        processed = {
            "date": datetime.datetime.now().strftime("%d.%m.%Y"),
            "name": tourist_data.get("name","") or "",
            "phone": tourist_data.get("phone","") or "",
            "destination": tourist_data.get("destination","") or "",
            "dates": tourist_data.get("dates","") or "",
            "budget": tourist_data.get("budget","") or "",
            "group": tourist_data.get("group","") or "",
            "wishes": tourist_data.get("wishes","") or "",
            "status": "новый",
            "comments": tourist_data.get("comments","") or "",
            "source": tourist_data.get("source","") or "",
        }
        user_states[uid] = {"table":"tourists","_chat_tourist":processed,"step":"chat_analyzed"}
        try: await w.delete()
        except Exception: pass

        card_lines = ["<b>Данные из переписки:</b>\n"]
        field_labels = {"name":"ФИО","phone":"Контакт","destination":"Направление","dates":"Даты",
                        "budget":"Бюджет","group":"Состав","wishes":"Пожелания","source":"Источник",
                        "status":"Статус","comments":"Комментарии"}
        for key, label in field_labels.items():
            val = processed.get(key, "")
            if val:
                card_lines.append(f"{label}: {val[:150]}")
            else:
                card_lines.append(f"{label}: —")

        kb = _make_kb([
            [CallbackButton(text="Записать в базу", payload="chat_save_tourist")],
            [CallbackButton(text="Изм. ФИО", payload="ce_name"),
             CallbackButton(text="Изм. контакт", payload="ce_phone")],
            [CallbackButton(text="Изм. направление", payload="ce_destination"),
             CallbackButton(text="Изм. источник", payload="ce_source")],
            [CallbackButton(text=f"Статус: {processed.get('status','новый')}", payload="ce_status")],
            [CallbackButton(text="Не сохранять", payload="chat_skip")],
        ])
        await msg.answer(text="\n".join(card_lines), attachments=[kb])
    except Exception as e:
        logger.error(f"Chat analysis: {e}")
        try: await w.message.edit(text=f"Ошибка: {str(e)[:100].replace('<','&lt;').replace('>','&gt;')}")
        except Exception: pass

@router.message_callback(F.callback.payload == "chat_save_tourist")
async def cb_chat_save(event: MessageCallback):
    cb = event.callback
    msg = event.message
    uid = cb.user.user_id
    state = user_states.get(uid)
    if not state or not state.get("_chat_tourist"): return await event.bot.send_callback(cb.callback_id, notification=" ")
    t = state["_chat_tourist"]
    try:
        sheet = tourist_get_sheet()
        # Проверка дублей
        all_rows = sheet.get_all_values()
        name_lower = (t.get("name","") or "").lower().strip()
        phone_digits = set(re.findall(r'\d{7,}', t.get("phone","") or ""))
        dup_row = None
        for i, row in enumerate(all_rows):
            if i == 0: continue
            ex_name = (row[1] if len(row) > 1 else "").lower().strip()
            ex_phone = set(re.findall(r'\d{7,}', row[2] if len(row) > 2 else ""))
            if phone_digits and ex_phone and phone_digits & ex_phone: dup_row = i + 1; break
            if ex_name and name_lower and len(name_lower) > 3 and (ex_name == name_lower or name_lower in ex_name): dup_row = i + 1; break

        if dup_row:
            # Дополняем существующую запись
            existing = sheet.row_values(dup_row)
            for col_idx, key in enumerate(["date","name","phone","destination","dates","budget","group","wishes","","comments","source"]):
                if not key or key == "date": continue
                new_val = t.get(key, "")
                if not new_val: continue
                old_val = existing[col_idx] if col_idx < len(existing) else ""
                if not old_val:
                    sheet.update_cell(dup_row, col_idx + 1, safe_phone(new_val) if key == "phone" else new_val)
                elif new_val.lower().strip() != old_val.lower().strip() and key in ("wishes","comments"):
                    sheet.update_cell(dup_row, col_idx + 1, f"{old_val}\n{new_val}")
            # Сохраняем скрипт в столбец L
            script = t.get("script","")
            if script:
                old_script = existing[11] if len(existing) > 11 else ""
                sheet.update_cell(dup_row, 12, script[:5000])
            await msg.edit(text=f"Данные {t.get('name','')} дополнены!")
        else:
            row = [t.get("date",""), t.get("name",""), safe_phone(t.get("phone","")),
                   t.get("destination",""), t.get("dates",""), t.get("budget",""),
                   t.get("group",""), t.get("wishes",""), "новый", t.get("comments",""),
                   t.get("source",""), t.get("script","")[:5000]]
            sheet.append_row([str(v) if v else "" for v in row], value_input_option="USER_ENTERED")
            await msg.edit(text=f"{t.get('name','')} записан в базу!")

        user_states.pop(uid, None)
        await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"Chat save: {e}")
        await event.bot.send_callback(cb.callback_id, notification=" ")

