# ==================== ЗАДАЧИ: ФУНКЦИИ ====================

TASK_STATUS_ICON = {"новая":"⚪","в работе":"🔵","выполнена":"✅","отменена":"❌"}

def _task_render_list(tasks, title):
    lines = [f"<b>{title} ({len(tasks)})</b>\n"]
    for i, t in enumerate(tasks, 1):
        st = TASK_STATUS_ICON.get((t.get("status","") or "").lower(),"⚪")
        dl = f" [до {t['deadline']}]" if t.get("deadline") else ""
        owner = f" ({t['owner']})" if t.get("owner") else ""
        line = f"{st} {i}. {t['task'][:90]}{owner}{dl}"
        if t.get("comment"):
            line += f"\n   💬 {t['comment'][:80]}"
        lines.append(line)
    return "\n".join(lines)

def _task_list_kb(tasks, mode="active"):
    """mode: archive / active. Кнопки-номера задач + переключатель режима."""
    rows = []; cur = []
    for i, t in enumerate(tasks[:30], 1):
        cur.append(CallbackButton(text=str(i), payload=f"topen_{t['row_num']}_{mode}"))
        if len(cur) == 6: rows.append(cur); cur = []
    if cur: rows.append(cur)
    toggle = ("📦 Архив", "tlist_archive") if mode == "active" else ("◀ К активным", "tlist_active")
    rows.append([CallbackButton(text=toggle[0], payload=toggle[1])])
    return _make_kb(rows)

def _task_card_text(t):
    st = TASK_STATUS_ICON.get((t.get("status","") or "").lower(),"⚪")
    lines = [f"{st} <b>Задача #{t['row_num']}</b>",
             f"\n{t.get('task','')}"]
    if t.get("owner"): lines.append(f"\n👤 {t['owner']}")
    else: lines.append("\n👤 — без ответственного —")
    if t.get("deadline"): lines.append(f"📅 до {t['deadline']}")
    if t.get("date"): lines.append(f"<i>создано {t['date']}</i>")
    lines.append(f"📌 Статус: {t.get('status','новая')}")
    if t.get("comment"): lines.append(f"\n💬 {t['comment']}")
    return "\n".join(lines)

def _task_card_kb(row_num, status):
    rows = []
    if (status or "").lower() != "выполнена":
        rows.append([CallbackButton(text="✅ Выполнено", payload=f"tdone_{row_num}")])
    else:
        rows.append([CallbackButton(text="↩ Вернуть в работу", payload=f"tundo_{row_num}")])
    rows.append([CallbackButton(text="👤 Назначить", payload=f"townm_{row_num}"),
                 CallbackButton(text="🔄 Статус", payload=f"tstm_{row_num}")])
    rows.append([CallbackButton(text="✏️ Дополнить", payload=f"tapp_{row_num}"),
                 CallbackButton(text="📝 Комментарий", payload=f"tcom_{row_num}")])
    rows.append([CallbackButton(text="◀ К активным", payload="tlist_active")])
    return _make_kb(rows)

def task_get_sheet():
    try: return gc.open_by_key(SPREADSHEET_ID_TASKS).sheet1
    except Exception as e: logger.error(f"Task sheet: {e}"); return None

def task_get_all():
    sheet = task_get_sheet()
    if not sheet: return []
    rows = sheet.get_all_values()
    result = []
    for i, r in enumerate(rows):
        if i == 0: continue
        if not any((c or "").strip() for c in r): continue
        result.append({
            "row_num": i + 1,
            "date": r[0] if len(r) > 0 else "",
            "task": r[1] if len(r) > 1 else "",
            "owner": r[2] if len(r) > 2 else "",
            "deadline": r[3] if len(r) > 3 else "",
            "status": r[4] if len(r) > 4 else "новая",
            "comment": r[5] if len(r) > 5 else "",
        })
    return result

def task_get_by_row(row_num):
    for t in task_get_all():
        if t["row_num"] == row_num: return t
    return None

def _parse_task(text):
    """Парсинг задачи без Claude: ответственный, дедлайн, текст."""
    owner = ""
    task = text.strip()
    task_lower = task.lower()
    for person in TASK_PEOPLE:
        pl = person.lower()
        if pl in task_lower or pl.split()[0] in task_lower:
            owner = person
            break
    if not owner:
        m = re.match(r'^([А-ЯЁа-яёA-Za-z]+(?:\s+[А-ЯЁA-Z])?)[:\-–—]\s*(.+)', task)
        if m:
            owner = m.group(1).strip()
            task = m.group(2).strip()
    if not owner:
        m2 = re.search(r'\bдля\s+([А-ЯЁа-яёA-Za-z]+(?:\s+[А-ЯЁA-Z])?)\b', task, re.IGNORECASE)
        if m2:
            owner = m2.group(1).strip()
    deadline = ""
    dl = re.search(r'(?:до|дедлайн|deadline)\s+(\d{1,2}[.\-/]\d{1,2}(?:[.\-/]\d{2,4})?)', task, re.IGNORECASE)
    if dl:
        deadline = dl.group(1).replace("-", ".").replace("/", ".")
        if len(deadline.split(".")) == 2:
            deadline += f".{datetime.datetime.now().year}"
    return task, owner, deadline

async def task_add(msg, text):
    try:
        task, owner, deadline = _parse_task(text)
        sheet = task_get_sheet()
        row = [datetime.datetime.now().strftime("%d.%m.%Y"), task, owner, deadline, "новая", ""]
        sheet.append_row([str(v) if v else "" for v in row], value_input_option="USER_ENTERED")
        parts = [f"✅ Задача создана\n\n{task}"]
        if owner: parts.append(f"Ответственный: {owner}")
        if deadline: parts.append(f"Дедлайн: {deadline}")
        await msg.answer(text="\n".join(parts))
    except Exception as e:
        logger.error(f"Task add: {e}")
        err = str(e)[:100].replace("<","&lt;").replace(">","&gt;")
        await msg.answer(text=f"Ошибка: {err}")

