async def task_complete(msg, query):
    """Старый текстовый сценарий — на случай если кто-то напишет команду текстом."""
    tasks = task_get_all()
    active = [t for t in tasks if (t.get("status","") or "").lower() not in ("выполнена","отменена")]
    q = query.strip()
    target = None
    if q.isdigit():
        idx = int(q) - 1
        if 0 <= idx < len(active): target = active[idx]
    if not target:
        for t in active:
            if fuzzy_match(q.lower(), t.get("task","").lower()): target = t; break
    if not target:
        await msg.answer(text=f"Задача «{query}» не найдена.", attachments=[KB_TASKS]); return
    try:
        sheet = task_get_sheet()
        sheet.update_cell(target["row_num"], 5, "выполнена")
        await msg.answer(text=f"✅ «{target['task']}» — выполнена!", attachments=[KB_TASKS])
    except Exception as e:
        await msg.answer(text=f"Ошибка: {str(e)[:80]}")

# ==================== МЕДИАТЕКА: ФУНКЦИИ ====================

def media_get_sheet():
    try: return gc.open_by_key(SPREADSHEET_ID_MEDIA).sheet1
    except Exception as e: logger.error(f"Media sheet: {e}"); return None

def media_get_all():
    sheet = media_get_sheet()
    if not sheet: return []
    rows = sheet.get_all_values()
    result = []
    for i, r in enumerate(rows):
        if i == 0: continue
        if not any((c or "").strip() for c in r): continue
        result.append({
            "row_num": i + 1,
            "date": r[0] if len(r) > 0 else "",
            "name": r[1] if len(r) > 1 else "",
            "type": r[2] if len(r) > 2 else "",
            "link": r[3] if len(r) > 3 else "",
            "description": r[4] if len(r) > 4 else "",
            "tags": r[5] if len(r) > 5 else "",
        })
    return result

async def media_add(msg, text):
    """Добавить материал без Claude — парсинг регулярками."""
    try:
        urls = re.findall(r'https?://\S+', text)
        link = urls[0] if urls else ""
        mtype = "видео" if any(x in link.lower() for x in ["youtu","vimeo","rutube"]) else "PDF" if ".pdf" in link.lower() else "ссылка"
        # Название = текст без ссылки
        name = re.sub(r'https?://\S+', '', text).strip()[:100] or link[:50]
        sheet = media_get_sheet()
        row = [datetime.datetime.now().strftime("%d.%m.%Y"), name, mtype, link, text, ""]
        sheet.append_row([str(v) if v else "" for v in row], value_input_option="USER_ENTERED")
        await msg.answer(text=f"✅ Добавлено: {name}\nТип: {mtype}")
    except Exception as e:
        err = str(e)[:100].replace("<","&lt;").replace(">","&gt;")
        await msg.answer(text=f"Ошибка: {err}")

async def media_search(msg, query):
    q = query.lower().strip()
    if len(q) < 3:
        await msg.answer(text="Слишком короткий запрос — введи минимум 3 символа (так находит точнее).", attachments=[KB_MEDIA]); return
    items = media_get_all()
    found = [m for m in items if fuzzy_match(q, " ".join([m.get("name",""),m.get("description",""),m.get("tags","")]))]
    if not found:
        await msg.answer(text=f"По запросу «{query}» ничего не найдено.", attachments=[KB_MEDIA]); return
    lines = [f"<b>Найдено: {len(found)}</b>\n"]
    for m in found:
        name = m.get("name","—")
        mtype = m.get("type","")
        link = m.get("link","")
        desc = m.get("description","")
        line = f"• <b>{name}</b>"
        if mtype: line += f" [{mtype}]"
        if link: line += f"\n  {link}"
        if desc: line += f"\n  {desc[:100]}"
        lines.append(line)
    text = "\n".join(lines)
    if len(text) > 4000: text = text[:4000]
    await msg.answer(text=text, attachments=[KB_MEDIA])

async def media_show_all(msg):
    items = media_get_all()
    if not items:
        await msg.answer(text="Медиатека пуста.", attachments=[KB_MEDIA]); return
    lines = [f"<b>Медиатека ({len(items)})</b>\n"]
    for m in items[-20:]:
        name = m.get("name","—")
        mtype = m.get("type","")
        link = m.get("link","")
        line = f"• <b>{name}</b>"
        if mtype: line += f" [{mtype}]"
        if link: line += f"\n  {link}"
        lines.append(line)
    text = "\n".join(lines)
    if len(text) > 4000: text = text[:4000]
    await msg.answer(text=text, attachments=[KB_MEDIA])

# ==================== ВИЗЫ: ФУНКЦИИ ====================

def visa_get_all():
    """Читает все страны и визы из таблицы. Таблица имеет парные столбцы: Страна|Виза|_|Страна|Виза|_|Страна|Виза"""
    try:
        sheet = gc.open_by_key(SPREADSHEET_ID_VISAS).sheet1
        rows = sheet.get_all_values()
        result = []
        if not rows: return result
        # Определяем пары столбцов (Страна, Виза) — каждые 3 столбца (A-B, D-E, G-H)
        header = rows[0]
        pairs = []
        for i, h in enumerate(header):
            if h.lower().strip() == "страна":
                visa_col = i + 1
                if visa_col < len(header):
                    pairs.append((i, visa_col))
        if not pairs:
            # Fallback: просто A=страна, B=виза
            pairs = [(0, 1)]
        for row in rows[1:]:
            for country_col, visa_col in pairs:
                country = (row[country_col] if country_col < len(row) else "").strip()
                visa = (row[visa_col] if visa_col < len(row) else "").strip()
                if country:
                    result.append({"country": country, "visa": visa})
        return result
    except Exception as e:
        logger.error(f"Visa sheet: {e}")
        return []

async def visa_search(msg, query):
    """Поиск визовых требований по стране."""
    all_visas = visa_get_all()
    if not all_visas:
        await msg.answer(text="Не удалось загрузить базу виз.", attachments=[KB_MAIN]); return
    q = query.lower().strip()
    found = [v for v in all_visas if fuzzy_match(q, v.get("country",""))]
    if not found:
        await msg.answer(text=f"Страна «{query}» не найдена в базе виз.\n\nПопробуй другое написание.", attachments=[KB_MAIN])
        return
    lines = []
    for v in found:
        country = v.get("country","")
        visa = v.get("visa","")
        lines.append(f"🛂 <b>{country}</b>\n{visa}\n")
    text = "\n".join(lines)
    if len(text) > 4000:
        parts = []
        while len(text) > 4000:
            cut = text[:4000].rfind("\n\n")
            if cut < 1000: cut = 4000
            parts.append(text[:cut]); text = text[cut:]
        parts.append(text)
        for p in parts: await msg.answer(text=p)
    else:
        await msg.answer(text=text)
    # Предлагаем искать ещё
    user_states[msg.sender.user_id] = {"table": "visas", "step": "visa_search"}
    await msg.answer(text="Ещё страна? Напиши или нажми ◀ Главная:", attachments=[KB_MAIN])

