# ==================== ПОДПИСКИ: УТИЛИТЫ ====================

def subs_fmt(amount) -> str:
    try:
        val = float(str(amount).replace(" ", "").replace(",", "."))
        if val == int(val):
            return f"{int(val):,}".replace(",", " ")
        return f"{val:,.2f}".replace(",", " ").replace(".", ",")
    except Exception:
        return str(amount)

def subs_to_float(s) -> float:
    try:
        return float(str(s).replace(" ", "").replace(",", "."))
    except Exception:
        return 0.0

def subs_calc_monthly(amount, period_months) -> float:
    try:
        months = max(1, int(period_months))
    except Exception:
        months = 1
    return round(subs_to_float(amount) / months, 2)

def subs_period_label(months) -> str:
    """Преобразует количество месяцев в читаемый ярлык."""
    try:
        m = int(months)
    except Exception:
        return "месяц"
    if m == 1:   return "месяц"
    if m == 3:   return "квартал"
    if m == 6:   return "полгода"
    if m == 12:  return "год"
    if m == 24:  return "2 года"
    if m == 36:  return "3 года"
    if m % 12 == 0: return f"{m // 12} лет"
    return f"{m} мес."

def subs_get_sheet():
    sh = gc.open_by_key(SPREADSHEET_ID_SUBS).sheet1
    if not sh.row_values(1):
        sh.append_row(SUBS_HEADERS)
    return sh

def subs_get_all() -> list:
    sh = subs_get_sheet()
    rows = sh.get_all_values()
    if len(rows) <= 1:
        return []
    headers = rows[0]
    result = []
    for i, row in enumerate(rows[1:], start=2):
        padded = row + [""] * max(0, len(headers) - len(row))
        d = dict(zip(headers, padded))
        name = str(d.get("Название", "")).strip()
        if not name:
            continue
        d["_row"] = i
        result.append(d)
    return result

def subs_menu_kb():
    return KB_SUBS

# ==================== ПОДПИСКИ: ОСНОВНОЙ ОБРАБОТЧИК ====================

async def handle_subs_text(event: MessageCreated):
    msg = event.message
    uid = msg.sender.user_id
    text = msg.body.text.strip()
    lower = text.lower()

    # Кнопки меню сбрасывают ожидание удаления
    SUBS_MENU = ("план на месяц", "все подписки", "ближайшие списания", "удалить подписку", "◀ назад", "◀ назад")
    if any(btn in lower for btn in SUBS_MENU):
        pending_delete.pop(uid, None)

    # Ожидаем номер для удаления (только если не нажата кнопка меню)
    if uid in pending_delete:
        await subs_do_delete(msg, uid, text)
        return

    if "план на месяц" in lower:
        wait = await msg.answer(text="считаю...")
        subs = subs_get_all()
        if not subs:
            return await wait.message.edit(text="таблица пустая — сначала добавьте подписки.")
        await wait.message.edit(text=subs_build_plan(subs))
        return
    elif "все подписки" in lower:
        await subs_show_all(msg)
        return
    elif "ближайшие списания" in lower:
        await subs_show_upcoming(msg)
        return
    elif "удалить подписку" in lower:
        await subs_ask_delete(msg, uid)
        return

    # Парсинг без Claude — регулярками
    fallback = subs_parse_fallback(text)
    if fallback:
        wait = await msg.answer(text="добавляю...")
        await subs_do_add(wait, [fallback])
    elif "сколько" in lower or "итого" in lower or "план" in lower:
        wait = await msg.answer(text="считаю...")
        await subs_do_ask(wait, text)
    else:
        await msg.answer(
            "не смог разобрать\n\n"
            "напишите так: «zoom 2000 в год» или «школа 15000 в месяц, 1-го»"
        )


def subs_parse_fallback(text: str) -> dict | None:
    """Резервный парсинг без Claude — по регуляркам.
    Работает для фраз вида 'ростелеком 650 в месяц, 1-го'."""
    t = text.lower().strip()

    # Сумма
    amount_match = re.search(r'(\d[\d\s]*(?:[.,]\d+)?)\s*(?:руб|р\.?|₽)?', t)
    if not amount_match:
        return None
    amount_str = amount_match.group(1).replace(" ", "").replace(",", ".")
    try:
        amount = float(amount_str)
    except Exception:
        return None

    # Период
    period_months = 1
    if re.search(r'три\s*год|3\s*год|36\s*мес', t):   period_months = 36
    elif re.search(r'два\s*год|2\s*год|24\s*мес', t): period_months = 24
    elif re.search(r'\bгод\b|ежегодн|годов|annual', t): period_months = 12
    elif re.search(r'квартал|три\s*мес|3\s*мес', t):  period_months = 3
    elif re.search(r'полгод|6\s*мес', t):             period_months = 6
    elif re.search(r'\bмес\b|ежемес|monthly', t):     period_months = 1

    # День
    day = None
    day_match = re.search(r'(\d{1,2})[\-–]?(?:го|г\.?)\b', t)
    if day_match:
        try:
            day = int(day_match.group(1))
        except Exception:
            pass

    # Месяц списания
    months_ru = {"январ": "январь","феврал": "февраль","март": "март","апрел": "апрель",
                 "май": "май","мае": "май","июн": "июнь","июл": "июль","август": "август",
                 "сентябр": "сентябрь","октябр": "октябрь","ноябр": "ноябрь","декабр": "декабрь"}
    month_name = None
    for key, val in months_ru.items():
        if key in t:
            month_name = val
            break

    # Название — слово(а) до суммы, исключая стоп-слова
    stop = {"в","за","на","по","руб","рублей","рубль","р","месяц","год","квартал","мес","числа","числе"}
    words_before = t[:amount_match.start()].split()
    name_parts = [w for w in words_before if w not in stop and not re.match(r'^\d', w)]
    name = " ".join(name_parts).strip().title() if name_parts else "подписка"

    return {
        "name": name,
        "category": "Подписки",
        "amount": amount,
        "period_months": period_months,
        "day": day,
        "month_name": month_name,
    }

async def subs_do_add(wait: Message, items: list):
    try:
        sh = subs_get_sheet()
        date_now = datetime.datetime.now().strftime("%d.%m.%Y")
        added = []
        for item in items:
            name          = str(item.get("name", "без названия")).replace('"', '«').replace("'", "»")
            category      = item.get("category", "Другое")
            amount        = subs_to_float(item.get("amount", 0))
            period_months = item.get("period_months", 1)
            day           = item.get("day") or "не указано"
            month_name    = item.get("month_name") or ""
            burden        = subs_calc_monthly(amount, period_months)
            period_label  = subs_period_label(period_months)

            # День списания: если указан месяц (напр. "в марте"), пишем его
            day_display = day
            if month_name and str(day) in ("не указано", "None", ""):
                day_display = month_name
            elif month_name:
                day_display = f"{day} ({month_name})"

            sh.append_row(
                [date_now, name, category, amount, period_label, day_display, burden],
                value_input_option="USER_ENTERED"
            )
            added.append(
                f"• «{name}» — {subs_fmt(amount)} руб./{period_label}, "
                f"в мес.: {subs_fmt(burden)} руб."
            )

        if len(added) == 1:
            item = items[0]
            name         = str(item.get("name", "без названия")).replace('"', '«').replace("'", "»")
            category     = item.get("category", "Другое")
            amount       = subs_to_float(item.get("amount", 0))
            period_months = item.get("period_months", 1)
            burden       = subs_calc_monthly(amount, period_months)
            period_label = subs_period_label(period_months)
            # Кнопки смены категории
            kb = _make_kb([
                [
                    CallbackButton(text="👨‍👩‍👧 Семья", payload="subs_cat_Семья"),
                    CallbackButton(text="💼 Работа", payload="subs_cat_Работа"),
                ],
                [
                    CallbackButton(text="📱 Подписки", payload="subs_cat_Подписки"),
                    CallbackButton(text="📦 Другое", payload="subs_cat_Другое"),
                ],
            ])
            await wait.message.edit(text=
                f"✅ добавил «{name}» ({category.lower()})\n"
                f"сумма: <b>{subs_fmt(amount)} руб.</b> / {period_label}\n"
                f"в месяц откладывать: <b>{subs_fmt(burden)} руб.</b>\n\n"
                f"изменить категорию:",
                attachments=[kb],
            )
        else:
            await wait.message.edit(text=
                f"✅ добавил {len(added)} подписки:\n\n" + "\n".join(added)
            )
    except Exception as e:
        logger.error(f"Subs add: {e}")
        await wait.message.edit(text=f"ошибка при записи: {str(e)[:100]}")

async def subs_do_ask(wait: Message, question: str):
    """Аналитика — считаем локально, без Claude."""
    try:
        subs = subs_get_all()
        if not subs:
            return await wait.message.edit(text="таблица пустая — сначала добавьте подписки.")
        await wait.message.edit(text=subs_build_plan(subs))
    except Exception as e:
        logger.error(f"Subs ask: {e}")
        await wait.message.edit(text=f"ошибка при анализе: {str(e)[:100]}")

def subs_get_monthly(s: dict) -> float:
    """Возвращает месячную нагрузку — из колонки или пересчитывает сам."""
    v = subs_to_float(s.get("В месяц (руб.)", 0))
    if v > 0:
        return v
    # Пересчёт если колонка пустая или 0
    amount = subs_to_float(s.get("Сумма", 0))
    period = str(s.get("Период", "месяц")).lower().strip()
    divisor = PERIOD_DIVISOR.get(period, 1)
    # Для нестандартных периодов типа "3 года" пробуем распарсить
    if divisor == 1 and period not in PERIOD_DIVISOR:
        m = re.search(r'(\d+)\s*(?:лет|год)', period)
        if m:
            divisor = int(m.group(1)) * 12
        else:
            m2 = re.search(r'(\d+)\s*мес', period)
            if m2:
                divisor = int(m2.group(1))
    return round(amount / max(divisor, 1), 2) if amount > 0 else 0.0

def subs_build_plan(subs: list) -> str:
    """Строит план на месяц: сначала по датам списания, потом итог по категориям."""
    total = 0.0
    lines = ["<b>📊 план на месяц</b>\n"]

    # --- Блок 1: по датам ---
    # Группируем по дню месяца (только те у кого есть конкретное число)
    by_day: dict = {}   # day_num -> [(name, amount_str, monthly)]
    no_day = []         # без конкретного числа

    for s in subs:
        name   = s.get("Название", "—")
        amount = subs_to_float(s.get("Сумма", 0))
        period = s.get("Период", "")
        monthly = subs_get_monthly(s)
        total  += monthly
        day_raw = str(s.get("День списания", "")).strip()

        # Пробуем вытащить число из дня списания
        dm = re.search(r'(\d{1,2})', day_raw)
        if dm and "месяц" in period.lower():
            d = int(dm.group(1))
            by_day.setdefault(d, []).append((name, subs_fmt(amount), period, subs_fmt(monthly)))
        else:
            no_day.append((name, subs_fmt(amount), period, subs_fmt(monthly), day_raw))

    if by_day:
        lines.append("<b>📅 по датам списания:</b>")
        for day in sorted(by_day.keys()):
            items_day = by_day[day]
            day_total = sum(subs_to_float(i[1]) for i in items_day)
            lines.append(f"\n  <b>{day}-го числа</b>")
            for name, amt, period, monthly in items_day:
                lines.append(f"    • {name} — {amt} руб./{period}")

    if no_day:
        lines.append("\n<b>📋 без конкретного числа:</b>")
        for name, amt, period, monthly, day_raw in no_day:
            day_note = f" ({day_raw})" if day_raw and day_raw != "не указано" else ""
            lines.append(f"  • {name} — {amt} руб./{period}{day_note} → {monthly} руб./мес.")

    # --- Блок 2: итог по категориям ---
    lines.append("\n<b>📂 по категориям:</b>")
    by_cat: dict = {}
    for s in subs:
        cat = s.get("Категория") or "Другое"
        by_cat.setdefault(cat, []).append(s)

    for cat, items in by_cat.items():
        items = [i for i in items if str(i.get("Название", "")).strip()]
        if not items:
            continue
        cat_total = sum(subs_get_monthly(i) for i in items)
        lines.append(f"\n  <b>{cat}</b> — {subs_fmt(cat_total)} руб./мес.")
        for i in items:
            m = subs_get_monthly(i)
            period = i.get("Период", "")
            amount = subs_fmt(subs_to_float(i.get("Сумма", 0)))
            lines.append(f"    • {i.get('Название','—')} — {amount} руб./{period} → {subs_fmt(m)} руб./мес.")

    lines.append(f"\n<b>итого в месяц: {subs_fmt(total)} руб.</b>")
    lines.append(f"<b>в год: {subs_fmt(total * 12)} руб.</b>")
    return "\n".join(lines)

async def subs_show_all(event: MessageCreated):
    msg = event.message
    subs = subs_get_all()
    if not subs:
        return await msg.answer(text="список пустой. добавьте первую подписку!", attachments=[subs_menu_kb()])

    by_cat: dict = {}
    total = 0.0
    for s in subs:
        cat = s.get("Категория") or "Другое"
        by_cat.setdefault(cat, []).append(s)
        total += subs_get_monthly(s)

    lines = ["<b>📋 все подписки</b>\n"]
    for cat, items in by_cat.items():
        items = [i for i in items if str(i.get("Название", "")).strip()]
        if not items:
            continue
        cat_total = sum(subs_get_monthly(i) for i in items)
        lines.append(f"\n<b>{cat}</b> — {subs_fmt(cat_total)} руб./мес.")
        for i in items:
            period  = i.get("Период", "")
            amount  = subs_fmt(subs_to_float(i.get("Сумма", 0)))
            day     = str(i.get("День списания", "")).strip()
            day_str = f", {day}" if day and day not in ("не указано", "") else ""
            lines.append(f"  • {i.get('Название','—')} — {amount} руб./{period}{day_str}")

    lines.append(f"\n<b>итого в месяц: {subs_fmt(total)} руб.</b>")
    lines.append(f"<b>в год: {subs_fmt(total * 12)} руб.</b>")
    await msg.answer(text="\n".join(lines), attachments=[subs_menu_kb()])

async def subs_show_upcoming(event: MessageCreated):
    msg = event.message
    """Ближайшие списания — считаем локально."""
    subs = subs_get_all()
    if not subs:
        return await msg.answer(text="таблица пустая.", attachments=[subs_menu_kb()])

    today = datetime.date.today()
    upcoming = []

    MONTHS_RU = {
        "январь":1,"февраль":2,"март":3,"апрель":4,"май":5,"июнь":6,
        "июль":7,"август":8,"сентябрь":9,"октябрь":10,"ноябрь":11,"декабрь":12
    }

    for s in subs:
        name   = s.get("Название","—")
        amount = subs_to_float(s.get("Сумма", 0))
        period = s.get("Период", "")
        day_raw = str(s.get("День списания","")).strip().lower()

        next_date = None

        # Случай 1: день — число (ежемесячное)
        day_match = re.search(r'(\d{1,2})', day_raw)
        if day_match and "месяц" in period.lower():
            day_num = int(day_match.group(1))
            try:
                candidate = today.replace(day=day_num)
                if candidate < today:
                    # Следующий месяц
                    if today.month == 12:
                        candidate = candidate.replace(year=today.year+1, month=1)
                    else:
                        candidate = candidate.replace(month=today.month+1)
                next_date = candidate
            except ValueError:
                pass

        # Случай 2: указан месяц словом (годовые/многолетние)
        elif day_raw and not day_match:
            for ru, mn in MONTHS_RU.items():
                if ru in day_raw:
                    yr = today.year
                    try:
                        candidate = datetime.date(yr, mn, 1)
                        if candidate < today:
                            candidate = datetime.date(yr+1, mn, 1)
                        next_date = candidate
                    except ValueError:
                        pass
                    break

        if next_date:
            delta = (next_date - today).days
            upcoming.append((delta, next_date, name, amount, period))

    if not upcoming:
        return await msg.answer(
            "нет данных о датах списания.\n\nукажите день при добавлении:\n«ростелеком 650 в месяц, 1-го»",
            attachments=[subs_menu_kb()]
        )

    upcoming.sort(key=lambda x: x[0])
    lines = [f"<b>🗓 ближайшие списания</b> (от {today.strftime('%d.%m.%Y')}):\n"]
    for delta, dt, name, amount, period in upcoming[:10]:
        if delta == 0:
            when = "сегодня"
        elif delta == 1:
            when = "завтра"
        elif delta <= 7:
            when = f"через {delta} дн."
        else:
            when = dt.strftime("%d.%m")
        lines.append(f"  • <b>{dt.strftime('%d.%m')}</b> — {name}: {subs_fmt(amount)} руб. ({period}) — {when}")

    await msg.answer(text="\n".join(lines), attachments=[subs_menu_kb()])

async def subs_ask_delete(msg, uid: int):
    subs = subs_get_all()
    if not subs:
        return await msg.answer(text="список пустой — нечего удалять.", attachments=[subs_menu_kb()])
    lines = ["выберите номер подписки для удаления:\n"]
    for i, s in enumerate(subs, start=1):
        name   = s.get("Название", "—")
        amount = subs_fmt(subs_to_float(s.get("Сумма", 0)))
        period = s.get("Период", "")
        lines.append(f"{i}. {name} — {amount} руб./{period}")
    lines.append("\nнапишите номер или «отмена».")
    pending_delete[uid] = [s["_row"] for s in subs]
    await msg.answer(text="\n".join(lines))

async def subs_do_delete(msg, uid: int, text: str):
    if text.lower().strip() == "отмена":
        pending_delete.pop(uid, None)
        return await msg.answer(text="удаление отменено.", attachments=[subs_menu_kb()])
    row_map = pending_delete.get(uid, [])
    try:
        idx = int(text.strip()) - 1
        if idx < 0 or idx >= len(row_map):
            raise ValueError
        real_row = row_map[idx]
    except (ValueError, IndexError):
        return await msg.answer(text="неверный номер. напишите число из списка или «отмена».")
    try:
        sh   = subs_get_sheet()
        name = sh.cell(real_row, 2).value
        sh.delete_rows(real_row)
        pending_delete.pop(uid, None)
        await msg.answer(text=f"🗑 «{name}» удалена.", attachments=[subs_menu_kb()])
    except Exception as e:
        logger.error(f"Subs delete: {e}")
        pending_delete.pop(uid, None)
        await msg.answer(text=f"ошибка при удалении: {str(e)[:80]}", attachments=[subs_menu_kb()])


@router.message_callback(F.payload.startswith("subs_cat_"))
async def cb_subs_cat(event: MessageCallback):
    cb = event.callback
    msg = event.message
    """Меняет категорию последней добавленной подписки."""
    new_cat = cb.payload[len("subs_cat_"):]
    try:
        sh = subs_get_sheet()
        all_vals = sh.get_all_values()
        # Последняя строка с данными
        last_row = len(all_vals)
        if last_row < 2:
            return await event.bot.send_callback(cb.callback_id, notification=" ")
        sh.update_cell(last_row, 3, new_cat)  # колонка 3 = Категория
        old_text = (msg.body.text or "") if msg.body else ""
        # Убираем строку «изменить категорию:» и кнопки
        new_text = re.sub(r'\nизменить категорию:.*', '', old_text, flags=re.DOTALL)
        new_text = new_text.rstrip() + f"\n\nкатегория обновлена: <b>{new_cat}</b>"
        await msg.edit(text=new_text, attachments=[None])
        await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"Subs cat change: {e}")
        await event.bot.send_callback(cb.callback_id, notification=" ")


# ==================== СТРАНЫ: МОДУЛЬ ====================

def travel_get_sheet():
    sh = gc.open_by_key(SPREADSHEET_ID_TRAVEL).sheet1
    first_row = sh.row_values(1)
    if not first_row or first_row[0] != "Дата начала":
        sh.update("A1:F1", [TRAVEL_HEADERS])
    return sh

def travel_get_all() -> list:
    sh = travel_get_sheet()
    rows = sh.get_all_values()
    if len(rows) <= 1:
        return []
    result = []
    for i, row in enumerate(rows[1:], start=2):
        padded = row + [""] * max(0, 6 - len(row))
        result.append({
            "date_start": padded[0],
            "date_end":   padded[1],
            "country":    padded[2],
            "city":       padded[3],
            "address":    padded[4],
            "note":       padded[5],
            "_row":       i,
        })
    return result

def travel_parse_date(s: str) -> str:
    """Приводит дату к ДД.ММ.ГГГГ. Возвращает пустую строку если не удалось."""
    if not s:
        return ""
    s = s.strip()
    # Уже в нужном формате ДД.ММ.ГГГГ
    if re.match(r'^\d{2}\.\d{2}\.\d{4}$', s):
        return s
    # ДД.ММ.ГГ → ДД.ММ.20ГГ
    m = re.match(r'^(\d{2})\.(\d{2})\.(\d{2})$', s)
    if m:
        return f"{m.group(1)}.{m.group(2)}.20{m.group(3)}"
    # Д.М.ГГГГ или Д.М.ГГ
    m = re.match(r'^(\d{1,2})\.(\d{1,2})\.(\d{2,4})$', s)
    if m:
        d, mo, y = m.group(1).zfill(2), m.group(2).zfill(2), m.group(3)
        if len(y) == 2: y = "20" + y
        return f"{d}.{mo}.{y}"
    return s  # вернём как есть если не смогли распознать

def travel_menu_kb():
    return KB_TRAVEL

async def handle_travel_text(event: MessageCreated):
    msg = event.message
    uid   = msg.sender.user_id
    text  = msg.body.text.strip()

    step = user_states.get(uid, {}).get("step")

    if step == "travel_search":
        user_states[uid].pop("step", None)
        await travel_search(msg, text); return

    if step == "travel_edit_select":
        await travel_edit_select(msg, uid, text); return

    if step == "travel_edit_field":
        await travel_edit_field(msg, uid, text); return

    # Парсинг без Claude — регулярками
    entry = travel_parse_fallback(text)
    if entry:
        wait = await msg.answer(text="добавляю...")
        await travel_do_add(wait, [entry])
    else:
        await msg.answer(
                "не смог разобрать 🤔\n\n"
                "попробуйте так:\n«Турция, Стамбул, 10-15 марта 2025, отель Pera Palace»"
            )

def travel_parse_fallback(text: str) -> dict | None:
    COUNTRIES = ["россия","турция","оаэ","таиланд","индонезия","бали","китай","египет",
                 "израиль","италия","испания","франция","германия","греция","кипр","черногория",
                 "мальдивы","куба","мексика","индия","вьетнам","камбоджа","япония","корея",
                 "сша","бразилия","аргентина","перу","колумбия","хорватия","чехия","венгрия",
                 "австрия","швейцария","нидерланды","бельгия","португалия","швеция","норвегия",
                 "уругвай","фиджи","сингапур","гонконг","австралия","сейшелы","оман","аргентина"]
    t = text.lower()
    country = ""
    for c in COUNTRIES:
        if c in t:
            country = c.title()
            break
    date_start = date_end = ""
    m = re.search(r'(\d{1,2}[.\-/]\d{1,2}(?:[.\-/]\d{2,4})?)\s*[-–]\s*(\d{1,2}[.\-/]\d{1,2}(?:[.\-/]\d{2,4})?)', text)
    if m:
        date_start = travel_parse_date(m.group(1).replace("-",".").replace("/","."))
        date_end   = travel_parse_date(m.group(2).replace("-",".").replace("/","."))
    else:
        m2 = re.search(r'\d{1,2}[.\-/]\d{1,2}(?:[.\-/]\d{2,4})?', text)
        if m2:
            date_start = date_end = travel_parse_date(m2.group(0).replace("-",".").replace("/","."))
    if not country and not date_start:
        return None
    return {"date_start": date_start, "date_end": date_end,
            "country": country, "city": "", "address": "", "note": ""}

async def travel_do_add(wait: Message, entries: list):
    try:
        sh = travel_get_sheet()
        lines = []
        for e in entries:
            ds      = travel_parse_date(e.get("date_start",""))
            de      = travel_parse_date(e.get("date_end",""))
            country = e.get("country","").strip()
            city    = e.get("city","").strip()
            address = e.get("address","").strip()
            note    = e.get("note","").strip()
            sh.append_row([ds, de, country, city, address, note], value_input_option="USER_ENTERED")
            parts = [p for p in [country, city] if p]
            date_str = f"{ds}" + (f"–{de}" if de and de != ds else "")
            lines.append("• " + ", ".join(parts) + (f" ({date_str})" if date_str else "")
                         + (f" — {address}" if address else ""))

        if len(lines) == 1:
            e  = entries[0]
            ds = travel_parse_date(e.get("date_start",""))
            de = travel_parse_date(e.get("date_end",""))
            date_disp = ds + (f" — {de}" if de and de != ds else "")
            reply_text = (
                f"✅ добавил поездку\n\n"
                f"🗺 <b>{e.get('country','')} {e.get('city','')}</b>\n"
                f"📅 {date_disp or 'не указано'}\n"
                f"🏨 {e.get('address','не указано')}"
                + (f"\n📝 {e.get('note','')}" if e.get('note') else "")
            )
        else:
            reply_text = f"✅ добавил {len(lines)} поездки:\n\n" + "\n".join(lines)

        # отправляем меню отдельным сообщением
        await wait.message.edit(text=reply_text)
        await wait.message.answer(text="готово 👆", attachments=[travel_menu_kb()])
    except Exception as e:
        logger.error(f"Travel add: {e}")
        await wait.message.edit(text=f"ошибка при записи: {str(e)[:100]}")

async def travel_show_all(event: MessageCreated):
    msg = event.message
    entries = travel_get_all()
    if not entries:
        return await msg.answer(text="база поездок пустая. добавьте первую поездку!", attachments=[travel_menu_kb()])

    by_country: dict = {}
    for e in entries:
        c = e.get("country") or "—"
        by_country.setdefault(c, []).append(e)

    lines = [f"<b>🌍 все поездки</b> ({len(entries)} записей)\n"]
    for country in sorted(by_country.keys()):
        trips = by_country[country]
        lines.append(f"\n<b>{country}</b>")
        for t in sorted(trips, key=lambda x: x.get("date_start","")):
            city    = t.get("city","")
            ds      = t.get("date_start","")
            de      = t.get("date_end","")
            address = t.get("address","")
            note    = t.get("note","")
            date_str = ds + (f"–{de}" if de and de != ds else "")
            city_str    = f" {city}"          if city    else ""
            date_str2   = f" [{date_str}]"    if date_str else ""
            address_str = f"\n    🏨 {address}" if address else ""
            note_str    = f"\n    📝 {note}"    if note    else ""
            lines.append(f"  •{city_str}{date_str2}{address_str}{note_str}")

    full = "\n".join(lines)
    # Разбиваем если длинно
    if len(full) > 3800:
        chunks, cur = [], ""
        for line in lines:
            if len(cur) + len(line) + 1 > 3800:
                chunks.append(cur); cur = line
            else:
                cur += "\n" + line
        if cur: chunks.append(cur)
        for i, chunk in enumerate(chunks):
            kb = travel_menu_kb() if i == len(chunks)-1 else None
            await msg.answer(chunk, attachments=[kb])
    else:
        await msg.answer(full, attachments=[travel_menu_kb()])

async def travel_search(msg, query: str):
    entries = travel_get_all()
    q = query.lower().strip()
    found = [e for e in entries
             if fuzzy_match(q, (e.get("country","") or ""))
             or fuzzy_match(q, (e.get("city","") or ""))
             or fuzzy_match(q, (e.get("address","") or ""))
             or fuzzy_match(q, (e.get("note","") or ""))]

    if not found:
        return await msg.answer(text=f"по запросу «{query}» ничего не найдено.", attachments=[travel_menu_kb()])

    lines = [f"<b>🔍 «{query}»</b> ({len(found)} записей)\n"]
    for e in sorted(found, key=lambda x: x.get("date_start","")):
        country = e.get("country","—")
        city    = e.get("city","")
        ds      = e.get("date_start","")
        de      = e.get("date_end","")
        address = e.get("address","")
        note    = e.get("note","")
        date_str    = ds + (f"–{de}" if de and de != ds else "")
        city_str    = f" {city}"          if city    else ""
        date_str2   = f" [{date_str}]"    if date_str else ""
        address_str = f"\n    🏨 {address}" if address else ""
        note_str    = f"\n    📝 {note}"    if note    else ""
        lines.append(f"  • <b>{country}</b>{city_str}{date_str2}{address_str}{note_str}")

    await msg.answer(text="\n".join(lines), attachments=[travel_menu_kb()])


