def expenses_get_sheet():
    """Лист 'Расходы поездки'. Создаёт если нет; авто-миграция со старой 5-колоночной шапки."""
    sp = gc.open_by_key(SPREADSHEET_ID_TRAVEL)
    try:
        sh = sp.worksheet(TRAVEL_EXPENSES_SHEET_NAME)
    except Exception:
        sh = sp.add_worksheet(title=TRAVEL_EXPENSES_SHEET_NAME, rows=1000, cols=10)
        sh.update("A1:F1", [EXPENSE_HEADERS])
        return sh
    first = sh.row_values(1)
    if first == EXPENSE_HEADERS:
        return sh
    # Старая шапка из 5 колонок (без «Поездка») — миграция со сдвигом данных
    if len(first) >= 4 and first[0] == "Дата" and "Поездка" not in first:
        old = sh.get_all_values()
        sh.clear()
        sh.update("A1:F1", [EXPENSE_HEADERS])
        for row in old[1:]:
            row = (row + [""] * 6)[:5]
            sh.append_row([row[0], "", row[1], row[2], row[3], row[4] if len(row) > 4 else ""],
                          value_input_option="USER_ENTERED")
    else:
        sh.update("A1:F1", [EXPENSE_HEADERS])
    return sh


def expenses_get_all() -> list:
    sh = expenses_get_sheet()
    rows = sh.get_all_values()
    out = []
    for i, r in enumerate(rows[1:], start=2):
        r = list(r) + [""] * max(0, 6 - len(r))
        out.append({
            "date": r[0], "trip_key": r[1], "category": r[2],
            "cur_sum": r[3], "rub_sum": r[4], "description": r[5],
            "_row": i,
        })
    return out


def trip_make_key(trip: dict) -> str:
    return f"{trip.get('date_start','')}|{trip.get('country','')}"


def trip_label(trip: dict) -> str:
    parts = [p for p in [trip.get('country',''), trip.get('city','')] if p]
    place = ", ".join(parts) or "—"
    ds = trip.get('date_start','')
    de = trip.get('date_end','')
    if ds and de and ds != de:
        date = f"{ds}–{de}"
    elif ds and not de:
        date = f"с {ds} (открытая)"
    elif ds:
        date = ds
    else:
        date = ""
    return f"{place} [{date}]" if date else place


def _parse_dmy(s: str):
    try:
        d, m, y = s.split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None


def trip_sort_key(trip: dict):
    d = _parse_dmy(trip.get("date_start",""))
    return d or datetime.date.min


def find_current_trip(trips: list = None):
    if trips is None:
        trips = travel_get_all()
    today = datetime.date.today()
    for t in trips:
        ds = _parse_dmy(t.get('date_start',''))
        de = _parse_dmy(t.get('date_end',''))
        if not ds:
            continue
        if not de and ds <= today:
            return t
        if de and ds <= today <= de:
            return t
    return None


# ==================== ПУТЕШЕСТВИЯ (группировка сегментов по датам) ====================
# Лист «Поездки» хранит по строке на каждый сегмент (страна/город). Несколько сегментов,
# идущих подряд по датам (разрыв ≤ JOURNEY_GAP_DAYS), считаем ОДНИМ путешествием.
JOURNEY_GAP_DAYS = 2
JOURNEYS_RECENT_LIMIT = 5

def build_journeys(trips: list = None) -> list:
    if trips is None:
        trips = travel_get_all()
    dated, undated = [], []
    for t in trips:
        ds = _parse_dmy(t.get("date_start", ""))
        if ds:
            de = _parse_dmy(t.get("date_end", ""))
            dated.append((ds, de or ds, de is None, t))
        else:
            undated.append(t)
    dated.sort(key=lambda x: x[0])
    journeys = []
    for ds, de, is_open, t in dated:
        if journeys and ds <= journeys[-1]["end"] + datetime.timedelta(days=JOURNEY_GAP_DAYS):
            j = journeys[-1]
            j["trips"].append(t)
            j["start"] = min(j["start"], ds)
            if de > j["end"]:           # «открытость» определяет сегмент с самой поздней датой конца
                j["end"] = de; j["open"] = is_open
        else:
            journeys.append({"start": ds, "end": de, "open": is_open, "trips": [t]})
    for t in undated:
        journeys.append({"start": None, "end": None, "open": False, "trips": [t]})
    for j in journeys:
        cs = []
        for t in j["trips"]:
            c = (t.get("country") or "").strip()
            if c and c not in cs: cs.append(c)
        j["countries"] = cs
        j["keys"] = [trip_make_key(t) for t in j["trips"]]
        j["repr_row"] = j["trips"][0]["_row"]
    journeys.sort(key=lambda j: j["start"] or datetime.date.min, reverse=True)
    return journeys

def journey_year(j):
    return j["start"].year if j["start"] else None

def journey_label(j) -> str:
    co = ", ".join(j["countries"]) or "—"
    if not j["start"]:
        return co
    ds = j["start"].strftime("%d.%m.%Y")
    if j["open"]:
        return f"{co} ({ds} — …)"
    de = j["end"].strftime("%d.%m.%Y")
    return f"{co} ({ds}–{de})" if de != ds else f"{co} ({ds})"

def current_journey():
    today = datetime.date.today()
    for j in build_journeys():
        if not j["start"]: continue
        if j["open"] and today >= j["start"]: return j
        if j["end"] and j["start"] <= today <= j["end"]: return j
    return None

def journey_card(j) -> str:
    co = ", ".join(j["countries"]) or "—"
    if j["start"]:
        ds = j["start"].strftime("%d.%m.%Y")
        de = "…" if j["open"] else j["end"].strftime("%d.%m.%Y")
        dates = f"{ds} — {de}"
    else:
        dates = "даты не указаны"
    lines = [f"📍 <b>Текущее путешествие</b>\n", f"🗺 <b>{co}</b>", f"📅 {dates}"]
    if len(j["trips"]) > 1:
        lines.append("\n<i>Сегменты:</i>")
        for t in sorted(j["trips"], key=trip_sort_key):
            seg = ", ".join(p for p in [(t.get('country') or '').strip(), (t.get('city') or '').strip()] if p)
            d = t.get('date_start', '')
            lines.append(f"  • {seg}{(' [' + d + ']') if d else ''}")
    return "\n".join(lines)

def build_journeys_kb(kind: str, view: str = "start") -> AttachmentButton:
    """kind: 'a' (записать расход) | 't' (итог).
    view: 'start' (годы если их >1, иначе свежие) | 'recent' | 'all' | 'years' | 'y<ГГГГ>' | 'nodate'.
    Индексы в callback — по build_journeys()."""
    journeys = build_journeys()
    indexed = list(enumerate(journeys))
    years = sorted({journey_year(j) for _, j in indexed if journey_year(j)}, reverse=True)
    has_nodate = any(j["start"] is None for _, j in indexed)
    if view == "start":
        view = "years" if len(years) > 1 else "recent"

    rows = []
    if view == "years":
        for y in years:
            cnt = sum(1 for _, j in indexed if journey_year(j) == y)
            rows.append([CallbackButton(text=f"{y} ({cnt})", payload=f"ejnav_{kind}_y{y}")])
        if has_nodate:
            rows.append([CallbackButton(text="Без дат", payload=f"ejnav_{kind}_nodate")])
        return _make_kb(rows)

    if view.startswith("y") and view[1:].isdigit():
        yr = int(view[1:]); shown = [(i, j) for i, j in indexed if journey_year(j) == yr]
    elif view == "nodate":
        shown = [(i, j) for i, j in indexed if j["start"] is None]
    elif view == "all":
        shown = indexed
    else:
        shown = indexed[:JOURNEYS_RECENT_LIMIT]

    cur = current_journey(); cur_idx = None
    if cur:
        for i, j in indexed:
            if j["keys"] == cur["keys"]: cur_idx = i; break
    pfx = "ejp" if kind == "a" else "etj"
    if kind == "a" and cur is not None and view == "recent":
        rows.append([CallbackButton(text=f"📍 {journey_label(cur)[:55]}", payload=f"ejp_{cur_idx}")])
    for i, j in shown[:40]:
        if view == "recent" and i == cur_idx and kind == "a":
            continue
        mark = "📍 " if i == cur_idx else ""
        rows.append([CallbackButton(text=f"{mark}{journey_label(j)[:58]}", payload=f"{pfx}_{i}")])

    nav = []
    if view == "recent" and len(indexed) > JOURNEYS_RECENT_LIMIT:
        nav.append(CallbackButton(text="Показать все", payload=f"ejnav_{kind}_all"))
    if len(years) > 1:
        nav.append(CallbackButton(text="📅 По годам", payload=f"ejnav_{kind}_years"))
    if view != "recent":
        nav.append(CallbackButton(text="◀ Свежие", payload=f"ejnav_{kind}_recent"))
    if nav: rows.append(nav)
    return _make_kb(rows)


# ==================== ЗАМЕТКИ ПУТЕШЕСТВИЯ (голос → дневник) ====================

def travel_notes_get_sheet():
    sp = gc.open_by_key(SPREADSHEET_ID_TRAVEL)
    try:
        return sp.worksheet(TRAVEL_NOTES_SHEET_NAME)
    except Exception:
        sh = sp.add_worksheet(title=TRAVEL_NOTES_SHEET_NAME, rows=1000, cols=3)
        sh.update("A1:C1", [TRAVEL_NOTES_HEADERS])
        return sh

DIARY_PROMPT = """Ты причёсываешь расшифровку голосовой заметки из путешествия в связный текст-дневник.
ПРАВИЛА:
- Пиши от первого лица, как личная дневниковая запись.
- НЕ превращай в список, шаги, пункты или инструкцию. Только сплошной связный текст (1–3 абзаца).
- Сохрани ВСЕ факты, места, имена, впечатления, суммы. Ничего не выдумывай и не добавляй.
- Поправь только пунктуацию, оговорки и слова-паразиты, чтобы читалось гладко.
- Верни ТОЛЬКО готовый текст заметки, без заголовков и пояснений."""

async def _diarize(text: str) -> str:
    """Лёгкая чистка расшифровки в дневниковый текст (fallback — исходный текст)."""
    try:
        r = await asyncio.to_thread(lambda: claude.messages.create(
            model=CLAUDE_MODEL, max_tokens=900, system=DIARY_PROMPT,
            messages=[{"role": "user", "content": text}],
        ))
        out = (r.content[0].text or "").strip()
        return out or text
    except Exception as e:
        logger.warning(f"Diarize: {e}")
        return text

async def save_travel_note(transcript: str):
    """Сохраняет голосовую заметку дневником к текущему (или самому свежему) путешествию.
    Возвращает (текст_заметки, подпись_путешествия)."""
    journeys = build_journeys()
    journey = current_journey() or (journeys[0] if journeys else None)
    key = journey["keys"][0] if journey else ""
    label = journey_label(journey) if journey else "(без поездки)"
    diary = await _diarize(transcript)
    sh = await asyncio.to_thread(travel_notes_get_sheet)
    today = datetime.date.today().strftime("%d.%m.%Y")
    await asyncio.to_thread(
        lambda: sh.append_row([today, key, diary], value_input_option="USER_ENTERED")
    )
    return diary, label


def expense_auto_category(description: str) -> str:
    d = (description or "").lower()
    for cat, words in CATEGORY_KEYWORDS.items():
        for w in words:
            if w in d:
                return cat
    return "Орг. моменты"


def detect_currency(word: str) -> str | None:
    w = (word or "").lower()
    if not w:
        return None
    for pat, code in CURRENCY_MAP:
        if pat in w:
            return code
    return None


def expense_parse(text: str) -> dict | None:
    """Парсит '100 юаней (1100 рублей) - за кофе' → {amount_cur, currency, amount_rub, description}."""
    t = (text or "").strip()
    if not t:
        return None
    # 1) первая числовая сумма
    m1 = re.search(r"(\d+(?:[  ]\d{3})*(?:[.,]\d+)?)", t)
    if not m1:
        return None
    amount_str = re.sub(r"[  ]", "", m1.group(1)).replace(",", ".")
    try:
        amount1 = float(amount_str)
    except Exception:
        return None
    rest = t[m1.end():]
    # 2) валюта сразу после числа
    cur_m = re.match(r"\s*([а-яёa-z€$£¥₽₩฿]+)", rest, re.IGNORECASE)
    cur_word = cur_m.group(1) if cur_m else ""
    cur_code = detect_currency(cur_word)
    after = rest[cur_m.end():] if (cur_m and cur_code) else rest
    # 3) опциональный (NNN рублей)
    rub_amount = None
    rub_m = re.match(
        r"\s*\(?\s*(\d+(?:[  ]\d{3})*(?:[.,]\d+)?)\s*(?:рубл|руб|₽|rub)[^\)]*\)?",
        after, re.IGNORECASE
    )
    if rub_m and cur_code != "RUB":
        rub_str = re.sub(r"[  ]", "", rub_m.group(1)).replace(",", ".")
        try:
            rub_amount = float(rub_str)
        except Exception:
            pass
        after = after[rub_m.end():]
    desc = after.strip(" -–—,.;:()\t\n")
    if cur_code in (None, "RUB"):
        return {"amount_cur": amount1, "currency": "RUB",
                "amount_rub": amount1, "description": desc}
    return {"amount_cur": amount1, "currency": cur_code,
            "amount_rub": rub_amount if rub_amount is not None else 0.0,
            "description": desc}


def _fmt_amount(x) -> str:
    try:
        f = float(x)
    except Exception:
        return str(x)
    if f.is_integer():
        return f"{int(f):,}".replace(",", " ")
    return f"{f:,.2f}".replace(",", " ").replace(".00", "")


# -------- UI: текущая поездка --------

async def travel_show_current(event: MessageCreated):
    msg = event.message
    journeys = build_journeys()
    cur = current_journey()
    if not cur:
        return await msg.answer(text="Сейчас нет активного путешествия. Создайте через «➕ Новая поездка».", attachments=[KB_TRAVEL])
    keys = set(cur["keys"])
    exps = [e for e in expenses_get_all() if e.get("trip_key") in keys]
    total_rub = 0.0
    for e in exps:
        try: total_rub += float(str(e.get("rub_sum","0")).replace(",", ".") or 0)
        except Exception: pass
    # индекс текущего путешествия для callback'ов
    cur_idx = next((i for i, j in enumerate(journeys) if j["keys"] == cur["keys"]), None)
    text = journey_card(cur) + f"\n\n💸 расходов: <b>{len(exps)}</b> на <b>{_fmt_amount(total_rub)} ₽</b>"
    kb_rows = []
    if cur_idx is not None:
        kb_rows = [
            [CallbackButton(text="💸 Добавить расход", payload=f"ejp_{cur_idx}")],
            [CallbackButton(text="📊 Итого", payload=f"etj_{cur_idx}")],
        ]
    await msg.answer(text=text, attachments=[_make_kb(kb_rows)] if kb_rows else None)


