# -------- handler: пользователь пишет строку расхода --------

CURRENCY_DISPLAY = {
    "USD": "доллар", "EUR": "евро", "GBP": "фунт", "CNY": "юань",
    "JPY": "иена", "KRW": "вона", "THB": "бат", "AED": "дирхам",
    "TRY": "лира", "KZT": "тенге", "RUB": "рубль",
}


async def handle_expense_text(event: MessageCreated):
    msg = event.message
    uid = msg.sender.user_id
    state = user_states.get(uid, {})
    text = (msg.body.text or "").strip()
    trip_key = state.get("_exp_trip_key", "")
    trip_label_cached = state.get("_exp_trip_label", "")
    if not trip_key:
        user_states.pop(uid, None)
        return await msg.answer(text="Сессия расходов потеряна. Нажми «💸 Добавить расход».", attachments=[KB_TRAVEL])

    # Ввод курса валюты для предыдущего расхода
    if state.get("step") == "expense_wait_rate":
        await _handle_expense_rate_input(msg)
        return

    parsed = expense_parse(text)
    if not parsed:
        return await msg.answer(
            "Не разобрал. Формат:\n"
            "«100 юаней - за кофе» (бот спросит курс)\n"
            "или «100 юаней (1100 рублей) - за кофе»\n"
            "или «500 за такси» (рубли)."
        )

    # Если валюта не рубль и пользователь не указал рубли в скобках — нужен курс
    if parsed["currency"] != "RUB" and parsed["amount_rub"] == 0.0:
        rates = state.get("_exp_rates", {})
        cur = parsed["currency"]
        if cur in rates:
            # Уже знаем курс из этой сессии — применяем без переспроса
            parsed["amount_rub"] = round(parsed["amount_cur"] * rates[cur], 2)
        else:
            # Спрашиваем курс
            user_states[uid] = {**state, "step": "expense_wait_rate", "_exp_pending": parsed}
            cur_name = CURRENCY_DISPLAY.get(cur, cur)
            await msg.answer(
                f"Какой курс <b>{cur}</b> ({cur_name})?\n"
                f"Напиши сколько ₽ за 1 {cur} (например: <code>13.5</code>).\n"
                f"<i>Применю к: {_fmt_amount(parsed['amount_cur'])} {cur} — {parsed['description'] or '(без описания)'}.\n"
                f"Этот курс запомню до выхода из режима расходов.</i>"
            )
            return

    await _save_parsed_expense(msg, parsed, trip_key, trip_label_cached)


async def _handle_expense_rate_input(event: MessageCreated):
    msg = event.message
    uid = msg.sender.user_id
    state = user_states.get(uid, {})
    pending = state.get("_exp_pending")
    trip_key = state.get("_exp_trip_key", "")
    trip_label_cached = state.get("_exp_trip_label", "")
    if not pending or not trip_key:
        user_states[uid] = {**state, "step": "expense_add"}
        state.pop("_exp_pending", None)
        return await msg.answer(text="Сессия с курсом потеряна. Напиши расход ещё раз.")

    raw = (msg.body.text or "").strip().lower()
    # выкидываем «руб», «₽», «за 1 …»
    raw = re.sub(r"[^\d.,]", "", raw.replace(",", "."))
    try:
        rate = float(raw)
    except Exception:
        return await msg.answer(text="Не понимаю число. Пришли курс цифрой (например <code>13.5</code>).")
    if not (0.0001 < rate < 10000):
        return await msg.answer(text="Курс выглядит странно. Пришли разумное значение (например <code>13.5</code>).")

    cur = pending["currency"]
    pending["amount_rub"] = round(pending["amount_cur"] * rate, 2)

    # Сохраняем курс в сессию — следующий расход в той же валюте не переспросим
    rates = state.get("_exp_rates", {})
    rates[cur] = rate

    new_state = {k: v for k, v in state.items() if k != "_exp_pending"}
    new_state["step"] = "expense_add"
    new_state["_exp_rates"] = rates
    user_states[uid] = new_state

    await _save_parsed_expense(msg, pending, trip_key, trip_label_cached, rate_hint=rate)


async def _save_parsed_expense(msg, parsed: dict, trip_key: str,
                               trip_label_cached: str, rate_hint: float | None = None):
    category = expense_auto_category(parsed["description"])
    today = datetime.date.today().strftime("%d.%m.%Y")
    cur_display = f'{_fmt_amount(parsed["amount_cur"])} {parsed["currency"]}'
    try:
        sh = expenses_get_sheet()
        sh.append_row(
            [today, trip_key, category, cur_display,
             _fmt_amount(parsed["amount_rub"]), parsed["description"]],
            value_input_option="USER_ENTERED"
        )
        all_vals = sh.get_all_values()
        last_row = len(all_vals)
    except Exception as e:
        logger.error(f"Expense add: {e}")
        return await msg.answer(text=f"ошибка записи: {str(e)[:80]}")

    rub_str = f" ({_fmt_amount(parsed['amount_rub'])} ₽)" if parsed["currency"] != "RUB" else ""
    rate_str = ""
    if rate_hint:
        rate_str = f" <i>[курс {parsed['currency']}: {_fmt_amount(rate_hint)}]</i>"
    rows = [[CallbackButton(text=f"→ {c}", payload=f"ecat_{last_row}_{i}")]
            for i, c in enumerate(EXPENSE_CATEGORIES) if c != category]
    text = (f"✅ <b>{category}</b>\n"
            f"{cur_display}{rub_str}{rate_str} — {parsed['description'] or '(без описания)'}\n"
            f"<i>📍 {trip_label_cached}</i>")
    if rows:
        text += "\n\nСменить категорию:"
    rows.append([CallbackButton(text="🗑 Удалить", payload=f"edel_{last_row}")])
    await msg.answer(text=text, attachments=[_make_kb(rows)])


@router.message_callback(F.payload.startswith("ecat_"))
async def cb_expense_category(event: MessageCallback):
    cb = event.callback
    msg = event.message
    try:
        _, row_str, idx_str = cb.payload.split("_")
        row = int(row_str); idx = int(idx_str)
        new_cat = EXPENSE_CATEGORIES[idx]
    except Exception:
        return await event.bot.send_callback(cb.callback_id, notification=" ")
    try:
        sh = expenses_get_sheet()
        sh.update_cell(row, 3, new_cat)  # колонка C — категория
    except Exception as e:
        logger.error(f"Expense recat: {e}")
        return await event.bot.send_callback(cb.callback_id, notification=" ")
    try:
        await msg.edit(attachments=[None])
    except Exception:
        pass
    await msg.answer(text=f"↻ категория: <b>{new_cat}</b>")
    await event.bot.send_callback(cb.callback_id, notification=" ")


