# ==================== ЛИЧНОЕ: ФУНКЦИИ ====================

def personal_get_sheet():
    try:
        sp = gc.open_by_key(PERSONAL_SHEET_ID)
        try:
            sh = sp.worksheet(PERSONAL_SHEET_NAME)
        except Exception:
            sh = sp.add_worksheet(title=PERSONAL_SHEET_NAME, rows=500, cols=4)
            sh.update("A1:D1", [PERSONAL_HEADERS])
        return sh
    except Exception as e:
        logger.error(f"Personal sheet: {e}"); return None

def personal_get_all():
    sheet = personal_get_sheet()
    if not sheet: return []
    rows = sheet.get_all_values()
    result = []
    for i, r in enumerate(rows):
        if i == 0: continue
        if not any((c or "").strip() for c in r): continue
        result.append({
            "row_num": i + 1,
            "date": r[0] if len(r) > 0 else "",
            "category": r[1] if len(r) > 1 else "",
            "desc": r[2] if len(r) > 2 else "",
            "status": r[3] if len(r) > 3 else "",
        })
    return result

def _detect_personal_category(text):
    """Определяет категорию по ключевым словам."""
    t = text.lower()
    if any(w in t for w in ["фильм","кино","сериал","серіал","movie","series","netflix","кинопоиск","ivi","okko","смотреть","форс-мажор","форс мажор","suits"]): return "Фильм"
    if any(w in t for w in ["песня","пісн","музыка","трек","song","spotify","music","альбом","яндекс музыка","youtube music"]): return "Музыка"
    if any(w in t for w in ["книга","книг","book","читать","прочитать","роман"]): return "Книга"
    if any(w in t for w in ["бренд","вещь","купить","магазин","одежда","обувь","сумка","zara","wildberries","ozon","lamoda"]): return "Бренд/Вещь"
    return "Другое"

async def personal_add(msg, text):
    """Добавить запись в Личное (без Claude)."""
    try:
        category = _detect_personal_category(text)
        sheet = personal_get_sheet()
        row = [datetime.datetime.now().strftime("%d.%m.%Y"), category, text, ""]
        sheet.append_row([str(v) if v else "" for v in row], value_input_option="USER_ENTERED")
        # Кнопка смены категории
        kb = _make_kb([
            [CallbackButton(text=c, payload=f"psetcat_{c}")] for c in PERSONAL_CATEGORIES
        ])
        await msg.answer(text=f"✅ Записано [{category}]\n\n{text[:200]}\n\nИзменить категорию:", attachments=[kb])
    except Exception as e:
        logger.error(f"Personal add: {e}")
        await msg.answer(text=f"Ошибка: {str(e)[:100]}")

@router.message_callback(F.payload.startswith("psetcat_"))
async def cb_personal_set_cat(event: MessageCallback):
    cb = event.callback
    msg = event.message
    new_cat = cb.payload[8:]
    try:
        sheet = personal_get_sheet()
        all_vals = sheet.get_all_values()
        last_row = len(all_vals)
        if last_row >= 2:
            sheet.update_cell(last_row, 2, new_cat)
        await msg.edit(text=f"✅ Категория: <b>{new_cat}</b>")
        await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        await event.bot.send_callback(cb.callback_id, notification=" ")

PERSONAL_PAGE_SIZE = 20

def _personal_done_kb(active, cat="все", page=0):
    """Кнопки-галочки по одной на запись (по 5 в ряд) + пагинация."""
    rows = []
    start = page * PERSONAL_PAGE_SIZE
    end = start + PERSONAL_PAGE_SIZE
    chunk = active[start:end]
    cur = []
    for i, item in enumerate(chunk, start + 1):
        cur.append(CallbackButton(text=f"✓ {i}", payload=f"pdone_{item['row_num']}_{cat}_{page}"))
        if len(cur) == 5:
            rows.append(cur); cur = []
    if cur: rows.append(cur)
    nav = []
    if start > 0:
        nav.append(CallbackButton(text="◀ Назад", payload=f"ppage_{cat}_{page-1}"))
    if end < len(active):
        nav.append(CallbackButton(text="Вперёд ▶", payload=f"ppage_{cat}_{page+1}"))
    if nav: rows.append(nav)
    return _make_kb(rows) if rows else None

def _personal_render(active, cat="все", page=0):
    title = "💫 Мой список" if cat == "все" else f"💫 {cat}"
    start = page * PERSONAL_PAGE_SIZE
    end = start + PERSONAL_PAGE_SIZE
    chunk = active[start:end]
    total_pages = (len(active) + PERSONAL_PAGE_SIZE - 1) // PERSONAL_PAGE_SIZE
    page_label = f" — стр. {page+1}/{total_pages}" if total_pages > 1 else ""
    lines = [f"<b>{title} ({len(active)}){page_label}</b>\n",
             "<i>Нажми ✓ номер чтобы отметить сделанным.</i>\n"]
    for i, item in enumerate(chunk, start + 1):
        cat_icon = {"Фильм":"🎬","Музыка":"🎵","Книга":"📚","Бренд/Вещь":"🛍","Другое":"📌"}.get(item["category"],"📌")
        prefix = f"{cat_icon} " if cat == "все" else ""
        lines.append(f"{prefix}{i}. {item['desc'][:80]}")
    return "\n".join(lines)

@router.message_callback(F.payload.startswith("pcat_"))
async def cb_personal_filter(event: MessageCallback):
    cb = event.callback
    msg = event.message
    cat = cb.payload[5:]
    items = personal_get_all()
    active = [i for i in items if (i.get("status","") or "").lower() != "сделано"]
    if cat != "все":
        active = [i for i in active if i.get("category","") == cat]
    if not active:
        await msg.answer(text=f"Нет записей в категории «{cat}».", attachments=[KB_PERSONAL])
        await event.bot.send_callback(cb.callback_id, notification=" "); return
    text = _personal_render(active, cat, 0)
    kb = _personal_done_kb(active, cat, 0)
    await msg.answer(text=text, attachments=[kb] if kb else KB_PERSONAL)
    await event.bot.send_callback(cb.callback_id, notification=" ")

async def personal_show_active(msg):
    items = personal_get_all()
    active = [i for i in items if (i.get("status","") or "").lower() != "сделано"]
    if not active:
        await msg.answer(text="Список пуст. Кидай что хочешь сохранить!", attachments=[KB_PERSONAL]); return
    text = _personal_render(active, "все", 0)
    kb = _personal_done_kb(active, "все", 0)
    await msg.answer(text=text, attachments=[kb] if kb else KB_PERSONAL)

@router.message_callback(F.payload.startswith("ppage_"))
async def cb_personal_page(event: MessageCallback):
    cb = event.callback
    msg = event.message
    parts = cb.payload.split("_")
    if len(parts) < 3:
        await event.bot.send_callback(cb.callback_id, notification=" "); return
    cat = parts[1]
    try: page = int(parts[2])
    except ValueError: page = 0
    items = personal_get_all()
    active = [i for i in items if (i.get("status","") or "").lower() != "сделано"]
    if cat != "все":
        active = [i for i in active if i.get("category","") == cat]
    if not active:
        try: await msg.edit(text="Список пуст.")
        except: pass
        await event.bot.send_callback(cb.callback_id, notification=" "); return
    text = _personal_render(active, cat, page)
    kb = _personal_done_kb(active, cat, page)
    try: await msg.edit(text=text, attachments=[kb])
    except Exception as e: logger.warning(f"Personal page: {e}")
    await event.bot.send_callback(cb.callback_id, notification=" ")

@router.message_callback(F.payload.startswith("pdone_"))
async def cb_personal_done_btn(event: MessageCallback):
    cb = event.callback
    msg = event.message
    # Формат: pdone_<row>_<cat>_<page>
    parts = cb.payload.split("_")
    if len(parts) < 4:
        await event.bot.send_callback(cb.callback_id, notification=" "); return
    try: row_num = int(parts[1])
    except ValueError: await event.bot.send_callback(cb.callback_id, notification=" "); return
    cat = parts[2]
    try: page = int(parts[3])
    except ValueError: page = 0
    try:
        sheet = personal_get_sheet()
        sheet.update_cell(row_num, 4, "сделано")
        items = personal_get_all()
        active = [i for i in items if (i.get("status","") or "").lower() != "сделано"]
        if cat != "все":
            active = [i for i in active if i.get("category","") == cat]
        if not active:
            try: await msg.edit(text="✅ Готово, список пуст.")
            except: pass
            await event.bot.send_callback(cb.callback_id, notification=" "); return
        # Если на странице больше нет записей — откатываемся на предыдущую
        total_pages = (len(active) + PERSONAL_PAGE_SIZE - 1) // PERSONAL_PAGE_SIZE
        if page >= total_pages: page = max(0, total_pages - 1)
        text = _personal_render(active, cat, page)
        kb = _personal_done_kb(active, cat, page)
        try: await msg.edit(text=text, attachments=[kb])
        except Exception as e: logger.warning(f"Personal refresh: {e}")
        await event.bot.send_callback(cb.callback_id, notification=" ")
    except Exception as e:
        logger.error(f"Personal done btn: {e}")
        await event.bot.send_callback(cb.callback_id, notification=" ")

async def personal_complete(msg, query):
    items = personal_get_all()
    active = [i for i in items if (i.get("status","") or "").lower() != "сделано"]
    target = None
    q = query.strip()
    if q.isdigit():
        idx = int(q) - 1
        if 0 <= idx < len(active): target = active[idx]
    if not target:
        for i in active:
            if fuzzy_match(q.lower(), i.get("desc","").lower()): target = i; break
    if not target:
        await msg.answer(text=f"«{query}» не найдено.", attachments=[KB_PERSONAL]); return
    try:
        sheet = personal_get_sheet()
        sheet.update_cell(target["row_num"], 4, "сделано")
        await msg.answer(text=f"✅ «{target['desc'][:80]}» — сделано!", attachments=[KB_PERSONAL])
    except Exception as e:
        await msg.answer(text=f"Ошибка: {str(e)[:80]}")

# ==================== ПАРОЛИ ТО: ФУНКЦИИ ====================

async def _fetch_html(url: str) -> str:
    import aiohttp
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "ru-RU,ru;q=0.9",
    }
    async with aiohttp.ClientSession() as session:
        async with session.get(url, headers=headers, timeout=aiohttp.ClientTimeout(total=12)) as resp:
            return await resp.text()


def _norm(text: str) -> str:
    """Схлопывает все пробелы/переносы в один пробел."""
    return re.sub(r"\s+", " ", text).strip()


async def fetch_pac_rates() -> str:
    """Парсит курсы USD/EUR из виджета 'Внутренний курс валют' на главной pac.ru."""
    try:
        html = await _fetch_html("https://www.pac.ru/")
        soup = BeautifulSoup(html, "html.parser")
        flat = _norm(soup.get_text())

        # PAC использует запятую: "74,7535" или точку "74.7535" — ищем оба варианта
        # Паттерн виджета: "1$ = 74,7535" и "1€ = 86,7687"
        m_usd = re.search(r'1\s*\$\s*[=:]\s*([\d]{2,3}[.,]\d{2,6})', flat)
        m_eur = re.search(r'1\s*€\s*[=:]\s*([\d]{2,3}[.,]\d{2,6})', flat)
        if m_usd and m_eur:
            usd = m_usd.group(1).replace(",", ".")
            eur = m_eur.group(1).replace(",", ".")
            return f"💱 <b>Курсы валют PAC Group</b>\n\n1 USD = {usd} ₽\n1 EUR = {eur} ₽\n\n<i>Источник: pac.ru</i>"

        # Запасной: ищем числа вида 7X,XXXX и 8X,XXXX рядом с $ и €
        m_usd = re.search(r'\$[^\d]{0,20}(7\d[.,]\d{2,6})', flat)
        m_eur = re.search(r'€[^\d]{0,20}(8\d[.,]\d{2,6})', flat)
        if m_usd and m_eur:
            usd = m_usd.group(1).replace(",", ".")
            eur = m_eur.group(1).replace(",", ".")
            return f"💱 <b>Курсы валют PAC Group</b>\n\n1 USD = {usd} ₽\n1 EUR = {eur} ₽\n\n<i>Источник: pac.ru</i>"

        # Последний запасной: ищем в сыром HTML до рендеринга (data-атрибуты / JSON в script)
        m_usd = re.search(r'["\']USD["\']\s*[,:].*?(7\d[.,]\d{2,6})', html, re.S)
        m_eur = re.search(r'["\']EUR["\']\s*[,:].*?(8\d[.,]\d{2,6})', html, re.S)
        if m_usd and m_eur:
            usd = m_usd.group(1).replace(",", ".")
            eur = m_eur.group(1).replace(",", ".")
            return f"💱 <b>Курсы валют PAC Group</b>\n\n1 USD = {usd} ₽\n1 EUR = {eur} ₽\n\n<i>Источник: pac.ru</i>"

        return "Не удалось найти курсы на сайте PAC Group.\nПроверьте вручную: pac.ru/help/currency/"
    except Exception as e:
        logger.error(f"fetch_pac_rates: {e}")
        return f"Ошибка при получении курса PAC Group: {str(e)[:100]}"


async def fetch_lavoyage_rates() -> str:
    """Парсит курс валют из шапки lavoyage.ru — 'Курс на ДД.ММ.ГГ: $ XX.XX, € XX.XX'."""
    try:
        html = await _fetch_html("https://lavoyage.ru/")
        soup = BeautifulSoup(html, "html.parser")
        # Схлопываем весь текст страницы в одну строку — убирает проблему разбивки по тегам
        flat = _norm(soup.get_text())

        m = re.search(r'Курс\s+на\s+([\d.]+)\s*:?\s*\$\s*([\d.,]+)\s*,?\s*€\s*([\d.,]+)', flat, re.I)
        if m:
            date, usd, eur = m.group(1), m.group(2), m.group(3)
            return f"💱 <b>Курс валют Ла Вояж</b>\n\nКурс на {date}:\n1 USD = {usd} ₽\n1 EUR = {eur} ₽\n\n<i>Источник: lavoyage.ru</i>"

        return "Не удалось найти курс на сайте Ла Вояж.\nПроверьте вручную: lavoyage.ru/status/"
    except Exception as e:
        logger.error(f"fetch_lavoyage_rates: {e}")
        return f"Ошибка при получении курса Ла Вояж: {str(e)[:100]}"


async def fetch_cruclub_rates() -> str:
    """Парсит блок 'КУРСЫ ВАЛЮТ CRUCLUB' со страницы cruclub.ru/agent/howto/book/."""
    try:
        html = await _fetch_html("https://www.cruclub.ru/agent/howto/book/")
        soup = BeautifulSoup(html, "html.parser")
        # Схлопываем весь текст — числа USD/EUR могут быть в соседних тегах
        flat = _norm(soup.get_text())

        m_usd = re.search(r'1\s*USD\s*=\s*([\d.,]+)\s*RU[BR]', flat, re.I)
        m_eur = re.search(r'1\s*EUR\s*=\s*([\d.,]+)\s*RU[BR]', flat, re.I)
        if m_usd and m_eur:
            return f"💱 <b>Курсы валют CruClub</b>\n\n1 USD = {m_usd.group(1)} ₽\n1 EUR = {m_eur.group(1)} ₽\n\n<i>Источник: cruclub.ru</i>"

        # Запасной: числа вида 74.64 рядом с USD/EUR без RUR
        m_usd = re.search(r'USD\s*=\s*([\d.,]+)', flat, re.I)
        m_eur = re.search(r'EUR\s*=\s*([\d.,]+)', flat, re.I)
        if m_usd and m_eur:
            return f"💱 <b>Курсы валют CruClub</b>\n\n1 USD = {m_usd.group(1)} ₽\n1 EUR = {m_eur.group(1)} ₽\n\n<i>Источник: cruclub.ru</i>"

        return "Не удалось найти курс на сайте CruClub.\nПроверьте вручную: cruclub.ru/agent/howto/book/"
    except Exception as e:
        logger.error(f"fetch_cruclub_rates: {e}")
        return f"Ошибка при получении курса CruClub: {str(e)[:100]}"


CALC_OPERATORS = {
    "PAC Group": fetch_pac_rates,
    "Ла Вояж":  fetch_lavoyage_rates,
    "CruClub":  fetch_cruclub_rates,
}


def passwords_get_all():
    """Читает данные из листа паролей туроператоров (не auth)."""
    try:
        sp = gc.open_by_key(PASSWORDS_SHEET_ID)
        # Берём первый лист который НЕ auth
        for ws in sp.worksheets():
            if ws.title.lower() != PASSWORDS_AUTH_SHEET:
                rows = ws.get_all_values()
                result = []
                for i, r in enumerate(rows):
                    if i == 0: continue
                    if not any((c or "").strip() for c in r): continue
                    result.append({
                        "operator": r[0] if len(r) > 0 else "",
                        "login": r[1] if len(r) > 1 else "",
                        "password": r[2] if len(r) > 2 else "",
                        "link": r[3] if len(r) > 3 else "",
                    })
                return result
        return []
    except Exception as e:
        logger.error(f"Passwords read: {e}")
        return []

async def passwords_show_all(msg):
    items = passwords_get_all()
    if not items:
        await msg.answer(text="База пуста или нет доступа к таблице.", attachments=[KB_PASSWORDS]); return
    lines = [f"<b>🔐 Туроператоры ({len(items)})</b>\n"]
    for item in items:
        lines.append(f"• <b>{item.get('operator','—')}</b>")
    text = "\n".join(lines) + "\n\nНапиши название чтобы увидеть логин/пароль."
    if len(text) > 4000: text = text[:4000]
    await msg.answer(text=text, attachments=[KB_PASSWORDS])

def _normalize_url(url: str) -> str:
    """Добавляет https:// если протокола нет. Возвращает '' для пустой строки."""
    u = (url or "").strip()
    if not u:
        return ""
    if not re.match(r"^https?://", u, re.IGNORECASE):
        u = "https://" + u
    return u


async def passwords_search(msg, query):
    items = passwords_get_all()
    q = query.lower().strip()
    found = [i for i in items if fuzzy_match(q, i.get("operator",""))]
    if not found:
        await msg.answer(text=f"По запросу «{query}» ничего не найдено.", attachments=[KB_PASSWORDS]); return
    lines = []
    site_buttons = []
    for item in found:
        op = item.get("operator", "—")
        lines.append(f"<b>🔐 {op}</b>")
        if item.get("login"): lines.append(f"Логин: <code>{item['login']}</code>")
        if item.get("password"): lines.append(f"Пароль: <code>{item['password']}</code>")
        link = item.get("link", "")
        norm = _normalize_url(link)
        if norm:
            # Кликабельная ссылка в тексте + отдельная inline-кнопка для одного тапа
            lines.append(f"Сайт: <a href=\"{norm}\">{link.strip()}</a>")
            label = f"🌐 {op} — открыть сайт" if len(found) > 1 else "🌐 Открыть сайт"
            # Telegram-кнопка с URL — без ограничений по длине, можно длинный URL
            site_buttons.append([LinkButton(text=label[:60], url=norm)])
        lines.append("")
    lines.append("\n⏳ <i>Это сообщение удалится через 60 секунд</i>")
    kb = _make_kb(site_buttons) if site_buttons else None
    sent = await msg.answer(text="\n".join(lines), attachments=[kb])
    # Восстановим reply-клавиатуру отдельным служебным сообщением (которое тоже удалится).
    asyncio.create_task(_delete_and_restore_kb(sent, msg, 60))

async def _delete_later(message, delay: int):
    try:
        await asyncio.sleep(delay)
        await message.delete()
    except Exception:
        pass

async def _delete_and_restore_kb(bot_msg, user_msg, delay: int):
    try:
        await asyncio.sleep(delay)
        try: await bot_msg.message.delete()
        except Exception: pass
        try: await user_msg.delete()
        except Exception: pass
        # Восстанавливаем клавиатуру
        try:
            uid = user_msg.sender.user_id
            await bot.send_message(user_id=uid, text="🔐 <i>Данные удалены из чата</i>", attachments=[KB_PASSWORDS])
        except Exception: pass
    except Exception:
        pass

# ==================== B2B ЗАКАЗЫ: ФУНКЦИИ ====================

def b2b_get_sheet():
    try:
        sp = gc.open_by_key(SPREADSHEET_ID_B2B)
        sh = sp.sheet1
        first = sh.row_values(1)
        if not first or first[0] != "Дата":
            sh.update("A1:E1", [B2B_HEADERS])
        return sh
    except Exception as e:
        logger.error(f"B2B sheet: {e}"); return None

def b2b_get_all():
    sheet = b2b_get_sheet()
    if not sheet: return []
    rows = sheet.get_all_values()
    result = []
    for i, r in enumerate(rows):
        if i == 0: continue
        if not any((c or "").strip() for c in r): continue
        result.append({
            "row_num": i + 1,
            "date": r[0] if len(r) > 0 else "",
            "contact": r[1] if len(r) > 1 else "",
            "subject": r[2] if len(r) > 2 else "",
            "agreements": r[3] if len(r) > 3 else "",
            "status": r[4] if len(r) > 4 else "",
        })
    return result

async def b2b_add(msg, text):
    """Добавить B2B заказ без Claude — записываем текст как есть."""
    try:
        # Пробуем разделить по запятой: "Иванов +7999, консультация, встреча 15.04"
        parts = [p.strip() for p in text.split(",", 2)]
        contact = parts[0] if len(parts) >= 1 else text
        subject = parts[1] if len(parts) >= 2 else ""
        agreements = parts[2] if len(parts) >= 3 else ""
        sheet = b2b_get_sheet()
        row = [datetime.datetime.now().strftime("%d.%m.%Y"), contact, subject, agreements]
        sheet.append_row([str(v) if v else "" for v in row], value_input_option="USER_ENTERED")
        await msg.answer(text=f"✅ Заказ B2B записан\n\n{contact}" + (f"\n{subject}" if subject else ""))
    except Exception as e:
        logger.error(f"B2B add: {e}")
        await msg.answer(text=f"Ошибка: {str(e)[:100]}")

async def b2b_search(msg, query):
    orders = b2b_get_all()
    q = query.lower().strip()
    found = [o for o in orders if fuzzy_match(q, " ".join([o.get("contact",""), o.get("subject",""), o.get("agreements","")]))]
    if not found:
        await msg.answer(text=f"По запросу «{query}» заказов не найдено.", attachments=[KB_B2B]); return
    lines = [f"<b>Найдено: {len(found)}</b>\n"]
    for o in found:
        lines.append(f"• <b>{o.get('contact','—')}</b>")
        if o.get("subject"): lines.append(f"  {o['subject'][:100]}")
        if o.get("agreements"): lines.append(f"  Договор.: {o['agreements'][:100]}")
        lines.append("")
    await msg.answer(text="\n".join(lines), attachments=[KB_B2B])

async def b2b_complete(msg, query):
    orders = b2b_get_all()
    active = [o for o in orders if (o.get("status","") or "").lower() not in ("выполнен","done","готово")]
    target = None
    q = query.strip()
    if q.isdigit():
        idx = int(q) - 1
        if 0 <= idx < len(active): target = active[idx]
    if not target:
        for o in active:
            if fuzzy_match(q.lower(), (o.get("contact","") + " " + o.get("subject","")).lower()):
                target = o; break
    if not target:
        await msg.answer(text=f"Заказ «{query}» не найден.", attachments=[KB_B2B]); return
    try:
        sheet = b2b_get_sheet()
        sheet.update_cell(target["row_num"], 5, "выполнен")
        await msg.answer(text=f"✅ Заказ «{target.get('contact','')}» — выполнен!", attachments=[KB_B2B])
    except Exception as e:
        await msg.answer(text=f"Ошибка: {str(e)[:80]}")

