async def _gemini_extract_recipe(parts: list) -> dict:
    """Извлекает структурированный рецепт из изображения/PDF/текста через Claude."""
    prompt = (
        "Извлеки рецепт из этого материала. Верни ТОЛЬКО JSON без markdown-блоков:\n"
        '{"title":"Название","ingredients":["ингредиент 1",...],"steps":["Шаг 1",...],'
        '"servings":"порции или null","time":"время или null"}\n'
        'Если это не рецепт — верни {"error":"Не рецепт"}.'
    )
    claude_content = []
    for p in parts:
        if "inline_data" in p:
            d = p["inline_data"]
            claude_content.append({"type": "image", "source": {
                "type": "base64", "media_type": d["mime_type"], "data": d["data"],
            }})
        elif "text" in p:
            claude_content.append({"type": "text", "text": p["text"]})
    claude_content.append({"type": "text", "text": prompt})

    resp = await asyncio.to_thread(
        claude.messages.create,
        model=CLAUDE_MODEL, max_tokens=4000,
        messages=[{"role": "user", "content": claude_content}],
    )
    raw = resp.content[0].text.strip()
    if raw.startswith("```"):
        raw = raw.split("\n", 1)[1] if "\n" in raw else raw[3:]
        raw = raw.rsplit("```", 1)[0].strip()
    return json.loads(raw)


def _create_recipe_notion_page(title: str, category: str, ingredients: list,
                                steps: list, servings: str, time_: str,
                                image_bytes: bytes | None = None) -> str | None:
    """Создаёт страницу рецепта в Notion."""
    import urllib.request, urllib.error
    hdrs = _notion_headers()
    cat_emoji = RECIPE_CAT_EMOJI.get(category, "🍴")

    children = []

    # Шапка-callout
    meta = "  |  ".join(filter(None, [f"⏱ {time_}" if time_ else "", f"🍽 {servings}" if servings else ""]))
    callout_text = [{"type": "text", "text": {"content": title}, "annotations": {"bold": True}}]
    if meta:
        callout_text.append({"type": "text", "text": {"content": f"\n{meta}"}, "annotations": {"color": "gray"}})
    children.append({"object": "block", "type": "callout", "callout": {
        "rich_text": callout_text,
        "icon": {"type": "emoji", "emoji": cat_emoji},
        "color": "yellow_background",
    }})

    children.append({"object": "block", "type": "paragraph", "paragraph": {"rich_text": [
        {"type": "text", "text": {"content": "Категория: "}, "annotations": {"bold": True, "color": "orange"}},
        {"type": "text", "text": {"content": category}},
    ]}})

    children.append({"object": "block", "type": "divider", "divider": {}})

    # Ингредиенты
    children.append({"object": "block", "type": "heading_2", "heading_2": {
        "rich_text": [{"type": "text", "text": {"content": "🛒 Ингредиенты"}}], "color": "orange",
    }})
    for ing in ingredients:
        children.append({"object": "block", "type": "bulleted_list_item", "bulleted_list_item": {
            "rich_text": [{"type": "text", "text": {"content": str(ing)[:500]}}]
        }})

    children.append({"object": "block", "type": "divider", "divider": {}})

    # Приготовление
    children.append({"object": "block", "type": "heading_2", "heading_2": {
        "rich_text": [{"type": "text", "text": {"content": "👨‍🍳 Приготовление"}}], "color": "green",
    }})
    for step in steps:
        children.append({"object": "block", "type": "numbered_list_item", "numbered_list_item": {
            "rich_text": [{"type": "text", "text": {"content": str(step)[:500]}}]
        }})

    # Фото
    if image_bytes:
        upload_id = _notion_upload_image(image_bytes, "recipe.jpg", "image/jpeg")
        if upload_id:
            children.append({"object": "block", "type": "divider", "divider": {}})
            children.append({"object": "block", "type": "image", "image": {
                "type": "file_upload", "file_upload": {"id": upload_id},
            }})

    parent_id = NOTION_RECIPES_PAGE_ID or NOTION_PARENT_PAGE_ID
    payload = {
        "parent": {"page_id": parent_id},
        "icon": {"type": "emoji", "emoji": cat_emoji},
        "properties": {"title": [{"type": "text", "text": {"content": title[:200]}}]},
        "children": children[:100],
    }
    req = urllib.request.Request(
        "https://api.notion.com/v1/pages",
        data=json.dumps(payload).encode("utf-8"),
        headers=hdrs, method="POST",
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    page_id = data.get("id")
    for i in range(0, len(children[100:]), 100):
        batch = children[100:][i:i+100]
        urllib.request.urlopen(urllib.request.Request(
            f"https://api.notion.com/v1/blocks/{page_id}/children",
            data=json.dumps({"children": batch}).encode("utf-8"),
            headers=hdrs, method="PATCH",
        ), timeout=30).read()
    return data.get("url")


def _fmt_recipe_preview(d: dict) -> str:
    lines = [f"<b>{d.get('title','Рецепт')}</b>"]
    if d.get("category"): lines.append(f"Категория: {RECIPE_CAT_EMOJI.get(d['category'],'')} {d['category']}")
    if d.get("servings"): lines.append(f"Порций: {d['servings']}")
    if d.get("time"): lines.append(f"Время: {d['time']}")
    ings = d.get("ingredients", [])
    if ings:
        lines.append("\n<b>Ингредиенты:</b>")
        for ing in ings[:12]: lines.append(f"• {ing}")
        if len(ings) > 12: lines.append(f"… ещё {len(ings)-12}")
    steps = d.get("steps", [])
    if steps:
        lines.append("\n<b>Приготовление:</b>")
        for i, s in enumerate(steps[:6], 1):
            lines.append(f"{i}. {s[:100]}{'…' if len(s)>100 else ''}")
        if len(steps) > 6: lines.append(f"… ещё {len(steps)-6} шагов")
    return "\n".join(lines)


async def _recipe_process_file(msg, uid: int, gemini_parts: list, image_bytes: bytes | None = None):
    """После Gemini-распознавания показывает превью и просит выбрать категорию."""
    w = await msg.answer(text="⏳ Распознаю рецепт...")
    try:
        result = await _gemini_extract_recipe(gemini_parts)
    except Exception as e:
        logger.error(f"Recipe gemini: {e}")
        await w.message.edit(text=f"❌ Не удалось распознать: {str(e)[:120]}")
        return
    if result.get("error"):
        await w.message.edit(text=f"❌ {result['error']}")
        return

    recipe_drafts[uid] = {
        "title": result.get("title", "Рецепт"),
        "ingredients": result.get("ingredients") or [],
        "steps": result.get("steps") or [],
        "servings": result.get("servings") or "",
        "time": result.get("time") or "",
        "image_bytes": image_bytes,
        "category": None,
    }
    user_states[uid] = {"step": "recipe_cat"}

    preview = _fmt_recipe_preview(recipe_drafts[uid])
    kb_rows = [[CallbackButton(text=f"{RECIPE_CAT_EMOJI[c]} {c}", payload=f"recipe_cat_{c}")]
               for c in RECIPE_CATEGORIES]
    kb = _make_kb(kb_rows)
    await w.message.edit(text=preview + "\n\n<b>Выбери категорию:</b>", attachments=[kb])


