@router.message_callback(F.callback.payload == "goal_show")
async def cb_goal_show(event: MessageCallback):
    cb = event.callback
    msg = event.message
    if not allowed(cb.user.user_id): return await event.bot.send_callback(cb.callback_id, notification=" ")
    lines = ["🎯 <b>Текущие цели</b>\n"]
    for key_fn, label in [
        (_goal_key_month, "Месяц"),
        (_goal_key_quarter, "Квартал"),
        (_goal_key_year, "Год"),
    ]:
        key = key_fn()
        goal = _goal_get(key)
        earned = _goal_period_income(key)
        lbl = _goal_label(key)
        if goal > 0:
            bar = _progress_bar(earned, goal)
            pct = min(earned / goal * 100, 100)
            lines.append(f"<b>{label} ({lbl})</b>")
            lines.append(f"{bar}")
            lines.append(f"💰 {_fmt_money(earned)} ₽ из {_fmt_money(goal)} ₽ ({pct:.0f}%)")
            left = max(goal - earned, 0)
            if left > 0:
                lines.append(f"До цели: {_fmt_money(left)} ₽")
        else:
            lines.append(f"<b>{label} ({lbl})</b>: <i>не задана</i>")
        lines.append("")
    await msg.answer(text="\n".join(lines))
    await event.bot.send_callback(cb.callback_id, notification=" ")


