@router.message_callback(F.payload.startswith("plan_idea_toggle_"))
async def cb_plan_idea_toggle(event: MessageCallback):
    cb = event.callback
    msg = event.message
    if not allowed(cb.user.user_id): return
    try:
        idx = int(cb.payload.split("_")[-1])
    except Exception:
        return await event.bot.send_callback(cb.callback_id, notification=" ")
    month = plan_current_month()
    sh = plan_get_sheet()
    rows = sh.get_all_values()
    idea_i = 0
    for row_i, r in enumerate(rows[1:], start=2):
        r = list(r) + [""] * max(0, 5 - len(r))
        if r[1] != month or r[0] not in ("идея", "идея_готово"):
            continue
        if idea_i == idx:
            new_typ = "идея" if r[0] == "идея_готово" else "идея_готово"
            sh.update_cell(row_i, 1, new_typ)
            await event.bot.send_callback(cb.callback_id, notification=" ")
            d = plan_get_data(month)
            lines = ["💡 <b>Идеи по заработку:</b>\n"]
            for i, idea in enumerate(d["ideas"]):
                mark = "✅" if idea["done"] else "⬜"
                lines.append(f"{mark} {i+1}. {idea['desc']}")
            kb = _make_kb([
                [CallbackButton(text="➕ Добавить идею", payload="plan_idea_new")],
                *[[CallbackButton(
                    text=f"{'↩️ Не готово' if d['ideas'][i]['done'] else '✅ Реализована'}: {d['ideas'][i]['desc'][:25]}",
                    callback_data=f"plan_idea_toggle_{i}"
                )] for i in range(len(d["ideas"]))]
            ])
            try:
                await msg.edit(text="\n".join(lines), attachments=[kb])
            except Exception:
                await msg.answer(text="\n".join(lines), attachments=[kb])
            return
        idea_i += 1
    await event.bot.send_callback(cb.callback_id, notification=" ")


async def main():
    logger.info("Bot starting...")
    await start_web_server()
    # Регистрируем хук для утренней сводки до старта планировщика
    try:
        import calendar_module as _cm
        _cm.morning_extras_callback = _morning_extras
        logger.info("Morning digest extras callback registered")
    except Exception as e:
        logger.warning(f"Morning extras hook: {e}")
    try:
        start_reminder_loop()
    except Exception as e:
        logger.error(f"start_reminder_loop: {e}")
    try:
        asyncio.ensure_future(monthly_report_loop())
        logger.info("Monthly report loop started")
        asyncio.ensure_future(motivation_loop())
        logger.info("Motivation loop started")
    except Exception as e:
        logger.error(f"monthly_report_loop: {e}")
    try:
        from email_module import start_email_poller
        start_email_poller(bot, ALLOWED_USERS)
    except Exception as e:
        logger.error(f"start_email_poller: {e}")
    await dp.start_polling(bot)

