def _reflection_sheet():
    """Возвращает лист Рефлексия в первой таблице."""
    sp = gc.open_by_key(SPREADSHEET_ID_1)
    try:
        return sp.worksheet(REFLECTION_SHEET_NAME)
    except Exception:
        ws = sp.add_worksheet(title=REFLECTION_SHEET_NAME, rows=2000, cols=5)
        ws.append_row(["Дата", "Тип", "Резюме", "Контент", "ID"])
        return ws


def _save_reflection_sync(content: str, entry_type: str, summary: str) -> str:
    """Сохраняет запись рефлексии в Google Sheets."""
    import datetime as _dt
    now = _dt.datetime.now(tz=_dt.timezone(_dt.timedelta(hours=3)))
    date_str = now.strftime("%d.%m.%Y %H:%M")
    ws = _reflection_sheet()
    ws.append_row([date_str, entry_type, summary, content[:3000], ""])
    return ""


async def reflection_handle_text(event: MessageCreated):
    msg = event.message
    uid = msg.sender.user_id
    text = (msg.body.text or "").strip()
    if not text or text in ("◀ Главная", "📝 Написать", "🎙 Голос/фото", "📊 Итоги", "🪞 Рефлексия"):
        return
    w = await msg.answer(text="💭 Сохраняю...")
    try:
        try:
            summary = await asyncio.wait_for(
                _claude_generate(f"Сделай краткое резюме (1 предложение, до 80 символов) для этой записи рефлексии:\n\n{text[:500]}"),
                timeout=20
            )
        except Exception:
            summary = text[:80]
        url = await asyncio.to_thread(_save_reflection_sync, text, "text", summary)
    except Exception as e:
        logger.error(f"reflection save text: {e}")
        await w.message.edit(text=f"❌ Ошибка сохранения: {str(e)[:120]}")
        return
    await w.message.edit(text=
        f"✅ <b>Сохранено!</b>\n\n<i>{summary}</i>",
        attachments=[KB_REFLECTION]
    )


async def reflection_handle_photo(event: MessageCreated):
    msg = event.message
    uid = msg.sender.user_id
    w = await msg.answer(text="🔍 Читаю скриншот...")
    try:
        import base64 as _b64
        data = await _download_attachment_bytes(msg)
        if not data:
            await w.message.edit(text="❌ Не удалось загрузить изображение.")
            return
        b64 = _b64.b64encode(data).decode()
        content = await _claude_generate_with_image(
            "Опиши что на этом скриншоте/изображении. Это запись рефлексии — извлеки основной смысл и мысли. Ответь по-русски.",
            b64, max_tokens=1500,
        )
        caption = ((msg.body.text or "") if msg.body else "").strip()
        if caption:
            content = f"{caption}\n\n{content}"
        summary = await _claude_generate(
            f"Краткое резюме (1 предложение, до 80 символов):\n\n{content[:500]}"
        )
        url = await asyncio.to_thread(_save_reflection_sync, content, "photo", summary)
    except Exception as e:
        logger.error(f"reflection photo: {e}")
        await w.message.edit(text=f"❌ Ошибка: {str(e)[:120]}")
        return
    btn = f'<a href="{url}">📖 Открыть в Notion</a>' if url else ""
    await w.message.edit(text=f"✅ <b>Сохранено!</b>\n\n<i>{summary}</i>\n\n{btn}", attachments=[KB_REFLECTION])


async def reflection_handle_voice(event: MessageCreated):
    msg = event.message
    uid = msg.sender.user_id
    w = await msg.answer(text="🎙 Расшифровываю голосовое...")
    try:
        transcript = await asyncio.wait_for(_transcribe_voice(msg), timeout=120)
        await w.message.edit(text="💭 Сохраняю...")
        try:
            summary = await asyncio.wait_for(
                _claude_generate(f"Сделай краткое резюме (1 предложение, до 80 символов) для этой голосовой заметки:\n\n{transcript[:500]}"),
                timeout=20
            )
        except Exception:
            summary = transcript[:80]
        url = await asyncio.to_thread(_save_reflection_sync, transcript, "voice", summary)
    except asyncio.TimeoutError:
        await w.message.edit(text="❌ Превышено время ожидания расшифровки. Попробуй ещё раз.")
        return
    except Exception as e:
        logger.error(f"reflection voice: {e}")
        err = str(e).replace("<", "&lt;").replace(">", "&gt;")
        await w.message.edit(text=f"❌ Ошибка расшифровки:\n<i>{err[:200]}</i>")
        return
    await w.message.edit(text=
        f"✅ <b>Сохранено!</b>\n\n<i>{summary}</i>",
        attachments=[KB_REFLECTION]
    )


async def reflection_summary(event: MessageCreated):
    msg = event.message
    uid = msg.sender.user_id
    if not allowed(uid): return
    w = await msg.answer(text="🔍 Читаю твои записи...")
    try:
        rows = await asyncio.to_thread(lambda: _reflection_sheet().get_all_values())
        # Пропускаем заголовок, берём последние 30 записей
        data_rows = [r for r in rows[1:] if len(r) >= 3 and r[0]]
        if not data_rows:
            await w.message.edit(text=
                "📭 Записей рефлексии пока нет.\n\n"
                "Добавь несколько записей — текстом, голосом или скриншотом."
            )
            return
        recent = data_rows[-30:]
        entries_text = "\n".join(
            f"[{r[0]}] ({r[1]}) {r[2]}: {r[3][:300]}" for r in recent
        )
    except Exception as e:
        logger.error(f"reflection summary load: {e}")
        await w.message.edit(text=f"❌ Не удалось загрузить записи: {str(e)[:150]}")
        return

    await w.message.edit(text="💭 Анализирую как коуч...")
    try:
        prompt = (
            f"{REFLECTION_COACH_PROMPT}\n\n"
            f"Вот записи рефлексии (дата, тип, резюме, текст):\n\n"
            f"{entries_text}\n\n"
            f"Проведи анализ: какие темы повторяются, какие эмоции прослеживаются, "
            f"что важно для роста. Задай 2-3 мощных коучинговых вопроса для дальнейшего исследования. "
            f"Пиши тепло, честно, конкретно. Без markdown-разметки."
        )
        analysis = await asyncio.wait_for(_claude_generate(prompt, max_tokens=2000), timeout=60)
    except asyncio.TimeoutError:
        await w.message.edit(text="❌ Gemini не ответил вовремя. Попробуй ещё раз через минуту.")
        return
    except Exception as e:
        logger.error(f"reflection summary gemini: {e}")
        await w.message.edit(text=f"❌ Ошибка анализа: {str(e)[:120]}")
        return
    await w.message.edit(text=
        f"🧠 <b>Коуч-анализ ({len(recent)} записей)</b>\n\n{analysis}",
        attachments=[KB_REFLECTION]
    )


